# ===== src/data.py =====
"""
src/data.py - Steps 1-3: load inputs, universe filter, per-month rank transform (spec: steps 1-3).
"""
import numpy as np
import polars as pl


def load_inputs(cfg):
    """Step 1: chars panel + target_month, 147 factor names, deduplicated 8-K filings."""
    f = cfg["data_files"]
    factors = pl.read_csv(f["factors"])["variable"].drop_nulls().to_list()
    panel = pl.read_parquet(f["chars"]).with_columns(
        pl.col("eom").cast(pl.Date),
        pl.col("eom").cast(pl.Date).dt.offset_by("1mo").dt.month_end().alias("target_month"))
    assert panel.select(["permno", "eom"]).is_duplicated().sum() == 0, "(permno, eom) not unique"
    cols = ["document_id", "permno", "filing_date", "items", "text", "text_sha256", "company_name", "ticker"]
    filings = (pl.read_parquet(f["8k"], columns=cols).drop_nulls("permno")
               .with_columns(pl.col("filing_date").cast(pl.Date))
               .sort(["filing_date", "document_id"])
               .unique(subset=["permno", "text_sha256"], keep="first", maintain_order=True))
    if cfg["smoke"]:  # seeded permno subsample
        ids = np.sort(panel["permno"].unique().to_numpy())
        keep = np.random.default_rng(cfg["seed"]).choice(ids, min(cfg["smoke_n_permnos"], len(ids)), replace=False)
        panel = panel.filter(pl.col("permno").is_in(keep))
        filings = filings.filter(pl.col("permno").is_in(keep))
    return panel, factors, filings


def short_eligible_mask(df, short_me_q, cfg):
    """Short-eligible expr: me_pct >= short_me_q, dolvol_pct >= short_dolvol_q, zero-trades <= universe median.
    Use as df.with_columns(short_eligible=short_eligible_mask(df, q, cfg)); df is unused (expression-based)."""
    return ((pl.col("me_pct") >= short_me_q) & (pl.col("dolvol_pct") >= cfg["short_dolvol_q"])
            & (pl.col("zt_raw") <= pl.col("zt_raw").median().over("eom"))).fill_null(False)


def build_universe(panel, cfg):
    """Step 2: per month, |prc| >= min and market_equity above the month's quantile (all stocks); raw copies kept."""
    me = pl.col("market_equity")
    df = panel.with_columns(
        prc_raw=pl.col("prc"), me_raw=me, dolvol_raw=pl.col("dolvol_126d"), zt_raw=pl.col("zero_trades_126d"),
        me_pct=me.rank("average").over("eom") / me.count().over("eom"),
        _cut=me.quantile(cfg["universe_me_q"]).over("eom"))
    df = df.filter((pl.col("prc").abs() >= cfg["min_abs_prc"]) & (me > pl.col("_cut"))).drop("_cut")
    return df.with_columns(
        dolvol_pct=pl.col("dolvol_raw").rank("average").over("eom") / pl.col("dolvol_raw").count().over("eom"),
        zt_pct=pl.col("zt_raw").rank("average").over("eom") / pl.col("zt_raw").count().over("eom"),
    ).with_columns(short_eligible=short_eligible_mask(None, cfg["short_me_q"], cfg))


def preprocess(univ, factors, cfg):
    """Step 3: missing flags from raw nulls (train rows), template rank to [-1,1] per month, nulls -> 0, sector."""
    train = univ.filter(pl.col("target_month") <= pl.lit("2018-12-31").str.to_date())
    miss = train.select([pl.col(c).is_null().mean() for c in factors]).row(0)
    flag_vars = [c for c, mm in zip(factors, miss) if mm is not None and mm > cfg["missing_flag_threshold"]]
    flag_cols = [c + "_miss" for c in flag_vars]
    out = univ.with_columns([pl.col(c).is_null().cast(pl.Int8).alias(c + "_miss") for c in flag_vars])

    def rk(c):  # template: dense rank - 1, / month max, *2 - 1; max == 0 -> 0; nulls -> 0
        r = pl.col(c).rank("dense").over("eom") - 1
        mx = r.max().over("eom")
        return pl.when(mx > 0).then(r / mx * 2 - 1).otherwise(0.0).fill_null(0.0).alias(c)
    out = out.with_columns([rk(c) for c in factors]).with_columns(sector=pl.col("gics").str.slice(0, 2).fill_null("NA"))
    return out, flag_cols


# ===== src/gru.py =====
"""
src/gru.py - Step 4: GRU autoencoder on 11 month-to-month changes of ranked features (trained <= 2018-11, then frozen).
"""
import copy
import numpy as np
import polars as pl
import torch
import torch.nn as nn


class _GruAE(nn.Module):
    """1-layer GRU encoder (hidden 64) -> linear to d; GRU decoder reconstructs the sequence from z."""
    def __init__(self, n_feat, d, hidden, seq):
        super().__init__()
        self.seq = seq
        self.enc, self.to_z = nn.GRU(n_feat, hidden, batch_first=True), nn.Linear(hidden, d)
        self.dec, self.out = nn.GRU(d, hidden, batch_first=True), nn.Linear(hidden, n_feat)

    def encode(self, x):
        return self.to_z(self.enc(x)[1][0])

    def forward(self, x):
        z = self.encode(x)
        return self.out(self.dec(z[:, None, :].expand(-1, self.seq, -1))[0]), z


def _gru_windows(df, factors, seq):
    """Dense (permno, month, feat) changes D and validity V; row indices (p, m) and valid-change counts per row."""
    mi = (df["eom"].dt.year() * 12 + df["eom"].dt.month() - 1).to_numpy().astype(np.int64)
    m = mi - (mi.min() - seq)  # pad so every window exists
    p_ids, p = np.unique(df["permno"].to_numpy(), return_inverse=True)
    X = np.full((len(p_ids), m.max() + 1, len(factors)), np.nan, np.float32)
    X[p, m] = df.select(factors).to_numpy().astype(np.float32)
    pres = ~np.isnan(X[:, :, 0])
    V = np.zeros(pres.shape, bool)
    V[:, 1:] = pres[:, 1:] & pres[:, :-1]  # change valid only between calendar-consecutive present months
    D = np.zeros_like(X)
    D[:, 1:] = np.where(V[:, 1:, None], X[:, 1:] - X[:, :-1], 0.0)
    nvalid = V[p[:, None], m[:, None] + np.arange(-seq + 1, 1)].sum(1)
    return D, V, p, m, nvalid


def _gru_batch(D, V, p, m, seq, dev):
    ix = m[:, None] + np.arange(-seq + 1, 1)
    return (torch.from_numpy(D[p[:, None], ix]).to(dev),
            torch.from_numpy(V[p[:, None], ix]).to(dev).float().unsqueeze(-1))


def _gru_loss(model, x, mask):
    xh, _ = model(x)
    return (mask * (xh - x) ** 2).sum() / (mask.sum() * x.shape[-1]).clamp(min=1)  # masked MSE


def gru_embeddings(df, factors, d, cfg):
    """Train on eom <= 2018-11, early-stop on 2019-2020 loss, pick weight decay, embed all (permno, eom)."""
    seq, dev, bs = cfg["gru_seq_len"], cfg["device"], cfg["gru_batch"]
    df = df.sort(["permno", "eom"])
    D, V, p, m, nvalid = _gru_windows(df, factors, seq)
    ok = nvalid >= cfg["gru_min_valid"]
    eom = df["eom"]
    tr_end = pl.Series([cfg["gru_train_end_eom"]]).str.to_date()[0]
    v0, v1 = [pl.Series([s]).str.to_date()[0] for s in cfg["gru_val_eom"]]
    tr = np.where(ok & (eom <= tr_end).to_numpy())[0]
    va = np.where(ok & ((eom >= v0) & (eom <= v1)).to_numpy())[0]
    if len(va) == 0:
        va = tr
    wd_losses, best = {}, None
    for wd in cfg["gru_wd_grid"]:
        torch.manual_seed(cfg["seed"])
        rng = np.random.default_rng(cfg["seed"])
        model = _GruAE(len(factors), d, cfg["gru_hidden"], seq).to(dev)
        opt = torch.optim.AdamW(model.parameters(), lr=cfg["gru_lr"], weight_decay=wd)
        best_l, best_sd, bad = np.inf, None, 0
        for _ in range(cfg["gru_max_epochs"]):
            model.train()
            perm = rng.permutation(tr)
            for i in range(0, len(perm), bs):
                b = perm[i:i + bs]
                x, mk = _gru_batch(D, V, p[b], m[b], seq, dev)
                opt.zero_grad()
                _gru_loss(model, x, mk).backward()
                nn.utils.clip_grad_norm_(model.parameters(), cfg["gru_clip"])
                opt.step()
            model.eval()
            with torch.no_grad():  # val loss: mean masked MSE over batches, weighted by batch size
                tot = sum(_gru_loss(model, *_gru_batch(D, V, p[va[i:i + bs]], m[va[i:i + bs]], seq, dev)).item()
                          * len(va[i:i + bs]) for i in range(0, len(va), bs)) / len(va)
            if tot < best_l - 1e-9:
                best_l, best_sd, bad = tot, copy.deepcopy(model.state_dict()), 0
            else:
                bad += 1
                if bad >= cfg["gru_patience"]:
                    break
        wd_losses[wd] = best_l
        if best is None or best_l < best[0]:
            best = (best_l, wd, best_sd)
    model = _GruAE(len(factors), d, cfg["gru_hidden"], seq).to(dev)
    model.load_state_dict(best[2])
    model.eval()
    emb = np.full((len(df), d), np.nan, np.float32)
    idx = np.where(ok)[0]
    with torch.no_grad():
        for i in range(0, len(idx), bs):
            b = idx[i:i + bs]
            emb[b] = model.encode(_gru_batch(D, V, p[b], m[b], seq, dev)[0]).cpu().numpy()
    out = df.select("permno", "eom").with_columns([pl.Series(f"gru_{j + 1}", emb[:, j]) for j in range(d)])
    return out, {"d": d, "best_wd": best[1], "val_loss": best[0], "wd_losses": wd_losses}


# ===== src/text.py =====
"""
src/text.py - Steps 6-7: 8-K event flags and FinBERT tone features per (permno, eom).
"""
import re
import numpy as np
import polars as pl
import torch


def _txt_idx(col="eom"):
    """Calendar month index (year*12 + month) of a Date expression."""
    c = pl.col(col)
    return c.dt.year().cast(pl.Int32) * 12 + c.dt.month().cast(pl.Int32)


def _txt_trailing(keys, monthly, offsets, aggs):
    """For each key (permno, eom): aggregate `monthly` (permno, idx, cols) over calendar months idx-o, o in offsets."""
    k = keys.select("permno", "eom").with_columns(_txt_idx().alias("idx"))
    parts = [k.with_columns((pl.col("idx") - o).alias("_j")) for o in offsets]
    k = pl.concat(parts).join(monthly.rename({"idx": "_j"}), on=["permno", "_j"], how="inner")
    return k.group_by("permno", "eom").agg(*aggs)


def event_flags(filings, keys, cfg):
    """Step 6: has_filing, n_filings, item_* (month t) and hist_* (12-month trailing counts, months t-11..t)."""
    ic = lambda it: it.replace(".", "_")
    f = filings.select("permno", "items", pl.col("filing_date").dt.month_end().alias("eom"))
    f = f.with_columns(
        [pl.col("items").list.contains(it).fill_null(False).cast(pl.Int8).alias(f"item_{ic(it)}") for it in cfg["items_flag"]]
        + [pl.col("items").list.contains(it).fill_null(False).cast(pl.Int8).alias(f"hist_{ic(it)}")
           for it in cfg["items_hist"]]
    )
    m = f.group_by("permno", "eom").agg(
        pl.len().alias("n_filings"),
        *[pl.col(f"item_{ic(it)}").max() for it in cfg["items_flag"]],
        *[pl.col(f"hist_{ic(it)}").sum().alias(f"hist_{ic(it)}") for it in cfg["items_hist"]],
    )
    cur = ["n_filings"] + [f"item_{ic(it)}" for it in cfg["items_flag"]]
    out = keys.select("permno", "eom").join(m.select("permno", "eom", *cur), on=["permno", "eom"], how="left")
    out = out.with_columns(pl.col("n_filings").is_not_null().cast(pl.Int8).alias("has_filing"))
    # history: sum monthly counts over t-11..t (calendar months); 0 when no filings in the window
    hc = [f"hist_{ic(it)}" for it in cfg["items_hist"]]
    h = _txt_trailing(keys, m.with_columns(_txt_idx().alias("idx")).select("permno", "idx", *hc), range(12),
                      [pl.col(c).sum() for c in hc])
    out = out.join(h, on=["permno", "eom"], how="left").with_columns([pl.col(c).fill_null(0) for c in hc])
    return out.select("permno", "eom", "has_filing", *cur, *hc)


# ---------------------------------------------------------------- FinBERT (step 7)
def _txt_load_model(cfg):
    """Returns (tokenizer, model in eval mode on cfg['device']). Separate so tests can replace it."""
    from transformers import AutoTokenizer, AutoModelForSequenceClassification
    tok = AutoTokenizer.from_pretrained(cfg["finbert_model"], use_fast=True)
    tok.model_max_length = int(1e9)  # we chunk manually; silence the length warning
    model = AutoModelForSequenceClassification.from_pretrained(cfg["finbert_model"]).to(cfg["device"]).eval()
    return tok, model


def _txt_anonymise(text, names, tickers):
    """Remove company names/tickers (word boundaries; names case-insensitive, tickers ALWAYS case-sensitive so ALL/NOW/FOR keep common words)."""
    def pat(words, flags):
        words = sorted({w.strip() for w in words if w and w.strip()}, key=len, reverse=True)
        if not words:
            return None
        return re.compile(r"(?<!\w)(?:" + "|".join(re.escape(w) for w in words) + r")(?!\w)", flags)
    ci = pat(list(names), re.IGNORECASE)
    cs = pat(list(tickers), 0)
    for p in (ci, cs):
        if p is not None:
            text = p.sub(" ", text)
    return text


def _txt_score_docs(docs, tok, model, cfg):
    """docs: list of clean texts -> list of (tone_mean, tone_min) (None, None if no tokens). Chunks sorted by length."""
    size, max_ch, bs = cfg["finbert_chunk_tokens"] - 2, cfg["finbert_max_chunks"], cfg["finbert_batch"]
    id2l = {int(i): str(l).lower() for i, l in model.config.id2label.items()}
    pos = next(i for i, l in id2l.items() if l.startswith("pos"))
    neg = next(i for i, l in id2l.items() if l.startswith("neg"))
    chunks = []  # (doc index, token ids)
    for s in range(0, len(docs), 64):
        enc = tok(docs[s:s + 64], add_special_tokens=False, truncation=False)["input_ids"]
        for j, ids in enumerate(enc):
            for c in range(0, min(len(ids), size * max_ch), size):
                chunks.append((s + j, ids[c:c + size]))
    order = sorted(range(len(chunks)), key=lambda i: len(chunks[i][1]))
    tones = np.zeros(len(chunks))
    dev = cfg["device"]
    for b in range(0, len(order), bs):
        idx = order[b:b + bs]
        L = max(len(chunks[i][1]) for i in idx) + 2
        ids = torch.full((len(idx), L), tok.pad_token_id, dtype=torch.long)
        mask = torch.zeros((len(idx), L), dtype=torch.long)
        for r, i in enumerate(idx):
            seq = [tok.cls_token_id] + chunks[i][1] + [tok.sep_token_id]
            ids[r, :len(seq)] = torch.tensor(seq)
            mask[r, :len(seq)] = 1
        with torch.inference_mode(), torch.autocast(device_type="cuda", dtype=torch.bfloat16, enabled=(dev == "cuda")):
            logits = model(input_ids=ids.to(dev), attention_mask=mask.to(dev)).logits
        p = torch.softmax(logits.float(), dim=-1).cpu().numpy()
        tones[idx] = p[:, pos] - p[:, neg]
    per = [[] for _ in docs]
    for (d, _), t in zip(chunks, tones):
        per[d].append(t)
    return [(float(np.mean(t)), float(np.min(t))) if t else (None, None) for t in per]


def finbert_doc_tones(filings, panel, cfg, save_every=2000):
    """Step 7: per-filing FinBERT tone (mean, min over <= 8 chunks), cached by document_id."""
    path = cfg["cache_dir"] / ("finbert_docs_smoke.parquet" if cfg["smoke"] else "finbert_docs.parquet")
    schema = {"document_id": pl.String, "tone_mean": pl.Float64, "tone_min": pl.Float64}
    cache = pl.read_parquet(path) if path.exists() else pl.DataFrame(schema=schema)
    f = filings.with_columns(pl.col("filing_date").dt.month_end().alias("eom"))
    pk = panel.select("permno", "eom").unique()
    f = f.join(pk, on=["permno", "eom"], how="semi")
    todo = f.filter(~pl.col("document_id").is_in(cache["document_id"].implode())).sort("document_id")
    if cfg.get("finbert_max_filings") is not None:
        todo = todo.head(cfg["finbert_max_filings"])
    if todo.height:
        # panel names/tickers for that permno-eom, used as extra anonymisation terms
        extra = {}
        if {"company_name", "ticker"} <= set(panel.columns):
            for r in panel.select("permno", "eom", "company_name", "ticker").iter_rows():
                extra[(r[0], r[1])] = (r[2], r[3])
        tok, model = _txt_load_model(cfg)
        todo = todo.select("document_id", "permno", "eom", "text", "company_name", "ticker")
        for s in range(0, todo.height, save_every):
            rows = todo.slice(s, save_every).to_dicts()
            docs = []
            for r in rows:
                pn, pt = extra.get((r["permno"], r["eom"]), (None, None))
                docs.append(_txt_anonymise(r["text"] or "", [r["company_name"], pn], [r["ticker"], pt]))
            sc = _txt_score_docs(docs, tok, model, cfg)
            new = pl.DataFrame({"document_id": [r["document_id"] for r in rows],
                                "tone_mean": [x[0] for x in sc], "tone_min": [x[1] for x in sc]}, schema=schema)
            cache = pl.concat([cache, new])
            cache.write_parquet(path)  # incremental save: a crash keeps progress
    return cache.filter(pl.col("document_id").is_in(f["document_id"].implode()))


def tone_features(filings, doc_tones, keys, cfg):
    """Per stock-month tone_mean, tone_min, tone_surprise = tone_mean - mean of monthly tone_mean over t-12..t-1."""
    f = (filings.select("document_id", "permno", pl.col("filing_date").dt.month_end().alias("eom"))
         .join(doc_tones, on="document_id", how="inner").drop_nulls("tone_mean"))
    m = f.group_by("permno", "eom").agg(pl.col("tone_mean").mean(), pl.col("tone_min").min())
    h = _txt_trailing(keys, m.with_columns(_txt_idx().alias("idx")).select("permno", "idx", "tone_mean"),
                      range(1, 13), [pl.col("tone_mean").mean().alias("_hist")])
    out = keys.select("permno", "eom").join(m, on=["permno", "eom"], how="left").join(h, on=["permno", "eom"], how="left")
    return out.select("permno", "eom", "tone_mean", "tone_min", (pl.col("tone_mean") - pl.col("_hist")).alias("tone_surprise"))


# ===== src/kalman.py =====
"""
src/kalman.py - Step 8: Kalman-filtered stock betas (4 noisy beta measures -> one state).
beta_t - m_t = phi (beta_{t-1} - m_{t-1}) + N(0,q);  m_t = sector median of beta_60m.
Sequential scalar updates per observation (own R_j); phi, q, R_j by exact Gaussian MLE on eom <= 2018-12, then frozen.
"""
from datetime import date

import numpy as np
import polars as pl
from scipy.optimize import minimize


def _kalman_grid(panel, cfg):
    """Dense arrays: permnos, month-ends, Y (n,T,J) observations, m (n,T) prior mean, first (n,) first month index, row index."""
    obs = cfg["kalman_obs"]
    df = panel.select("permno", "eom", "gics", *obs).with_columns(
        pl.col("gics").str.slice(0, 2).alias("sector"))
    months = pl.date_range(df["eom"].min(), df["eom"].max(), "1mo", eager=True).dt.month_end()
    permnos = df["permno"].unique().sort()
    pi = permnos.search_sorted(df["permno"]).to_numpy()
    ti = months.search_sorted(df["eom"]).to_numpy()
    n, T = len(permnos), len(months)
    Y = np.full((n, T, len(obs)), np.nan)
    for j, c in enumerate(obs):
        Y[pi, ti, j] = df[c].cast(pl.Float64).fill_nan(None).to_numpy(allow_copy=True)
    # prior mean: sector median of beta_60m per month, all-stock median where the sector median is null
    med = df.group_by("eom", "sector").agg(pl.col("beta_60m").median().alias("m_sec")).join(
        df.group_by("eom").agg(pl.col("beta_60m").median().alias("m_all")), on="eom")
    sec_of = (df.sort("eom").group_by("permno").agg(pl.col("sector").drop_nulls().first())
              .sort("permno"))["sector"]                                  # stock's first known sector
    secs = sorted(set(sec_of.drop_nulls().to_list()))
    sidx = np.array([secs.index(s) if s is not None else -1 for s in sec_of.to_list()])
    M_sec = np.full((len(secs) + 1, T), np.nan)                           # last row (idx -1) = no sector
    M_all = np.full(T, np.nan)
    mi = months.search_sorted(med["eom"]).to_numpy()
    M_all[mi] = med["m_all"].to_numpy()
    for s, t, v in zip(med["sector"].to_list(), mi, med["m_sec"].to_numpy()):
        if s is not None:
            M_sec[secs.index(s), t] = v
    M_all = np.where(np.isnan(M_all), np.nanmedian(M_all), M_all)
    m = np.where(np.isnan(M_sec[sidx]), M_all[None, :], M_sec[sidx])
    first = np.full(n, T)
    np.minimum.at(first, pi, ti)
    return permnos, months, Y, m, first, pi, ti


def _kalman_filter(Y, m, first, theta, t_end=None, full=False):
    """Vectorised-over-stocks filter. Returns loglik (and state, var, has_obs grids if full)."""
    phi = 1 / (1 + np.exp(-theta[0])); q = np.exp(theta[1]); R = np.exp(theta[2:])
    n, T, J = Y.shape
    T = T if t_end is None else t_end
    d = np.zeros(n); P = np.full(n, q / (1 - phi ** 2)); seen = np.zeros(n, bool)
    ll = 0.0
    out = np.zeros((3, n, T)) if full else None
    for t in range(T):
        if t > 0:                                                         # predict (also bridges missing months)
            d = phi * d                                                   # deviations from m_t
            P = phi ** 2 * P + q
        start = first == t                                                # initialise at first month: d=0, P=q/(1-phi^2)
        d = np.where(start, 0.0, d); P = np.where(start, q / (1 - phi ** 2), P)
        active = first <= t
        for j in range(J):
            y = Y[:, t, j] - m[:, t]
            ok = active & ~np.isnan(y)
            S = P + R[j]
            v = np.where(ok, y - d, 0.0)
            ll += -0.5 * np.sum(np.where(ok, np.log(2 * np.pi * S) + v ** 2 / S, 0.0))
            K = np.where(ok, P / S, 0.0)
            d = d + K * v; P = (1 - K) * P; seen |= ok
        if full:
            out[0, :, t], out[1, :, t], out[2, :, t] = d + m[:, t], P, seen
    return (ll, out) if full else ll


def kalman_betas(panel, cfg, r_floor=None):
    """-> (DataFrame[permno, eom, beta_kf, beta_var], params). Panel = raw (unranked) betas.
    r_floor: optional lower bound on every observation noise variance R_j (None = unconstrained MLE)."""
    permnos, months, Y, m, first, pi, ti = _kalman_grid(panel, cfg)
    J = Y.shape[2]
    t_fit = int((months <= date.fromisoformat(cfg["kalman_fit_end_eom"])).sum())
    lo, hi = np.nanpercentile(Y[:, :t_fit], 1, axis=(0, 1)), np.nanpercentile(Y[:, :t_fit], 99, axis=(0, 1))
    Y = np.clip(Y, lo, hi)                       # winsorise at the fit-sample 1/99 pct: raw betas have +-1e4 outliers (not in spec)
    x0 = np.array([2.0, np.log(0.02)] + [np.log(0.05)] * J)
    # R floor (not in spec): unconstrained MLE drives R(betabab_1260d) to its lower bound, so beta_kf copies that
    # 5-year shrunk beta; the step-10 beta check found the validation book's realised beta clearly nonzero.
    r_lo = -12 if r_floor is None else float(np.log(r_floor))
    if r_floor is not None:
        x0[2:] = np.maximum(x0[2:], r_lo)
    res = minimize(lambda th: -_kalman_filter(Y, m, first, th, t_fit), x0, method="L-BFGS-B",
                   bounds=[(-8, 8), (-12, 3)] + [(r_lo, 3)] * J)
    th = res.x
    params = {"phi": float(1 / (1 + np.exp(-th[0]))), "q": float(np.exp(th[1])),
              "R": {c: float(np.exp(r)) for c, r in zip(cfg["kalman_obs"], th[2:])}, "loglik": float(-res.fun),
              "r_floor": r_floor}
    _, out = _kalman_filter(Y, m, first, th, full=True)
    kf, var, seen = out[0, pi, ti], out[1, pi, ti], out[2, pi, ti].astype(bool)
    b60 = Y[pi, ti, cfg["kalman_obs"].index("beta_60m")]
    kf = np.where(seen, kf, np.where(np.isnan(b60), m[pi, ti], b60))      # no data yet -> beta_60m, else m_t
    df = panel.select("permno", "eom").with_columns(pl.Series("beta_kf", kf), pl.Series("beta_var", var))
    return df, params


# ===== src/cfi.py =====
"""
src/cfi.py - Clustered Feature Importance helpers (port of teammate's experience-cfi-xgboost src/fiam/cfi.py).
Factors are clustered on TRAIN months (median monthly Spearman, d = 1-|rho|, complete linkage); groups are permuted jointly
within each VALIDATION month; top-ranked groups form candidate factor subsets. Model tuning lives in src/ranker.py.
"""
import math
import warnings

import numpy as np
import polars as pl
from scipy.cluster.hierarchy import fcluster, linkage
from scipy.spatial.distance import squareform
from scipy.stats import rankdata


def _cfi_month_corr(X):
    """Spearman matrix of one month (ranked columns used as is, nulls already 0) and its stock count."""
    X = np.nan_to_num(X.astype("float64"))
    if len(X) < 3:
        return np.full((X.shape[1],) * 2, np.nan), len(X)
    with np.errstate(all="ignore"):
        return np.corrcoef(rankdata(X, axis=0).T), len(X)


def cfi_clusters(train_df, factors, cfg):
    """{cut: [groups]} - groups are lists of factor names. Under-documented pairs -> their factors stay singletons (last)."""
    p = len(factors)
    rhos, ns = [], []
    for _, d in train_df.group_by("eom", maintain_order=True):
        r, n = _cfi_month_corr(d.select(factors).to_numpy())
        rhos.append(r)
        ns.append(n)
    if rhos:
        rho = np.stack(rhos)
        valid = (np.array(ns)[:, None, None] >= cfg["cfi_min_pairs"]) & np.isfinite(rho)
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", RuntimeWarning)
            med = np.nanmedian(np.where(valid, rho, np.nan), axis=0)
        ok = valid.sum(axis=0) >= cfg["cfi_min_months"]
    else:
        med, ok = np.full((p, p), np.nan), np.zeros((p, p), bool)
    np.fill_diagonal(ok, True)
    bad = ~ok | ~np.isfinite(med)
    np.fill_diagonal(bad, False)
    iso = [i for i in range(p) if bad[i].any()]
    keep = [i for i in range(p) if i not in iso]
    Z = None
    if len(keep) > 1:
        D = 1.0 - np.abs(med[np.ix_(keep, keep)])
        D = np.clip((D + D.T) / 2.0, 0.0, None)
        np.fill_diagonal(D, 0.0)
        Z = linkage(squareform(D, checks=False), method="complete")
    out = {}
    for cut in cfg["cfi_cuts"]:
        labels = fcluster(Z, t=1.0 - cut, criterion="distance") if Z is not None else np.ones(len(keep))
        by = {}
        for i, lab in zip(keep, labels):
            by.setdefault(lab, []).append(i)
        groups = sorted(by.values(), key=lambda g: g[0]) + [[i] for i in iso]
        out[cut] = [[factors[i] for i in g] for g in groups]
    return out


def _cfi_mean_ic(eom, score, y):
    d = pl.DataFrame({"eom": eom, "s": score, "y": y}).drop_nulls("y").group_by("eom").agg(
        pl.corr(pl.col("s").rank(), pl.col("y").rank()).alias("ic"))["ic"].drop_nans().drop_nulls()
    return float(d.mean()) if len(d) else float("nan")


def _cfi_perm(eom, seed):
    """Row permutation that stays inside each month (months visited in sorted order, so (seed, month) is reproducible)."""
    rng = np.random.default_rng(seed)
    perm = np.arange(len(eom))
    order = np.argsort(eom, kind="stable")
    se = eom[order]
    for pos in np.split(order, np.flatnonzero(se[1:] != se[:-1]) + 1):
        perm[pos] = rng.permutation(pos)
    return perm


def cfi_importance(predict_fn, val_df, features, groups, cfg):
    """[(group_index, importance)]; importance = base mean monthly rank IC - mean over seeds of permuted IC."""
    X = val_df.select(features).cast(pl.Float32).to_numpy()
    eom, y = val_df["eom"], val_df["ret_exc_lead1m"]
    base = _cfi_mean_ic(eom, predict_fn(X), y)
    eom_np = eom.to_numpy()
    perms = [_cfi_perm(eom_np, cfg["seed"] + r) for r in range(cfg["cfi_repeats"])]
    idx = {f: i for i, f in enumerate(features)}
    out = []
    for gi, g in enumerate(groups):
        cols = [idx[f] for f in g]
        ics = []
        for perm in perms:
            Xp = X.copy()
            Xp[:, cols] = X[perm][:, cols]  # one permutation for every column of the group
            ics.append(_cfi_mean_ic(eom, predict_fn(Xp), y))
        out.append((gi, base - float(np.mean(ics))))
    return out


def cfi_candidates(groups, importances, shares):
    """Factor subsets: top ceil(share*n_groups) groups by importance (ties -> group order); duplicates dropped."""
    ranked = sorted(importances, key=lambda t: (-t[1], t[0]))
    seen, out = set(), []
    for s in shares:
        k = max(1, math.ceil(s * len(groups) - 1e-9))
        sub = [f for gi, _ in ranked[:k] for f in groups[gi]]
        if tuple(sub) not in seen:
            seen.add(tuple(sub))
            out.append(sub)
    return out


# ===== src/ranker.py =====
"""
src/ranker.py - Step 5: XGBRanker (rank:pairwise, qid = eom) with walk-forward windows, plus the Ridge baseline.
Scores are cross-sectional only; ret_hat comes from a rank regression fitted on validation scores of the train-only model.
"""
import calendar
from datetime import date

import numpy as np
import polars as pl
import xgboost as xgb
from sklearn.linear_model import Ridge



def _rk_me(s):
    """'YYYY-MM' -> month-end date."""
    y, m = int(s[:4]), int(s[5:7])
    return date(y, m, calendar.monthrange(y, m)[1])


def windows(cfg):
    """One dict per test year, by TARGET month: train 2015-02..Y-3, val Y-2..Y-1, test Y (2026 ends at last_test_month)."""
    first, last = _rk_me(cfg["first_train_month"]), _rk_me(cfg["last_test_month"])
    return [dict(year=y, train=(first, date(y - 3, 12, 31)), val=(date(y - 2, 1, 31), date(y - 1, 12, 31)),
                 test=(date(y, 1, 31), min(date(y, 12, 31), last))) for y in cfg["test_years"]]


def rank_ic(pred, cfg=None):
    """Monthly Spearman IC of score vs ret_exc_lead1m (Pearson on within-month average ranks); null targets dropped."""
    return (pred.drop_nulls("ret_exc_lead1m").group_by("eom")
            .agg(pl.corr(pl.col("score").rank(), pl.col("ret_exc_lead1m").rank()).alias("ic")).sort("eom"))


def _rk_mean_ic(eom, score, y):
    """Mean monthly rank IC from numpy arrays (months with undefined IC are skipped)."""
    ic = rank_ic(pl.DataFrame({"eom": eom, "score": score, "ret_exc_lead1m": y}))["ic"].drop_nans().drop_nulls()
    return float(ic.mean()) if len(ic) else float("nan")


def _rk_labels(eom, y):
    """Within-month decile 0-9 of y: floor(10*(rank_ordinal-1)/n)."""
    d = pl.DataFrame({"eom": eom, "y": y}).with_columns(
        (10 * (pl.col("y").rank("ordinal").over("eom") - 1) // pl.len().over("eom")).cast(pl.Int32).alias("l"))
    return d["l"].to_numpy()


def _rk_shuffle(eom, y, seed):
    """Permute y within each month (rows are sorted by eom, so blocks stay in place)."""
    order = np.lexsort((np.random.default_rng(seed).random(len(y)), eom.to_numpy()))
    return y[order]


def _rk_ranks(eom, score):
    """Within-month rank of score scaled to [-1, 1]."""
    d = pl.DataFrame({"eom": eom, "s": score}).with_columns(
        r=pl.col("s").rank().over("eom"), n=pl.len().over("eom"))
    return d.select(pl.when(pl.col("n") > 1).then((pl.col("r") - 1) / (pl.col("n") - 1) * 2 - 1).otherwise(0.0))["r"].to_numpy()


def _rk_mat(d, features):
    return d.select(features).cast(pl.Float32).to_numpy()  # nulls -> NaN (XGBoost handles them natively)


def _rk_xgb(cfg, depth, trees, X, y, e):
    kw = dict(device="cuda") if cfg["device"] == "cuda" and xgb.build_info().get("USE_CUDA") else {}
    m = xgb.XGBRanker(**cfg["xgb_fixed"], max_depth=depth, n_estimators=trees, random_state=cfg["seed"], **kw)
    m.fit(X, _rk_labels(e, y), qid=e.cast(pl.Int32).to_numpy())
    return m


def _rk_tune(tr, va, feats, cfg, ytr, yva, grid=None):
    """Fit on train per depth, eval val IC every eval_every trees. Returns (best_ic, depth, trees, model); fills grid if given."""
    Xtr, Xva = _rk_mat(tr, feats), _rk_mat(va, feats)
    best, best_m = (-np.inf, None, None), None
    for depth in cfg["xgb_depth_grid"]:
        m = _rk_xgb(cfg, depth, cfg["xgb_max_trees"], Xtr, ytr, tr["eom"])
        for k in range(cfg["xgb_eval_every"], cfg["xgb_max_trees"] + 1, cfg["xgb_eval_every"]):
            ic = _rk_mean_ic(va["eom"], m.predict(Xva, iteration_range=(0, k)), yva)
            if grid is not None:
                grid[f"{depth}_{k}"] = ic
            if ic > best[0]:
                best, best_m = (ic, depth, k), m
    return best[0], best[1], best[2], best_m


def _rk_cfi_select(tr, va, features, cfg, ytr, yva, base, cfi_factors):
    """CFI selection on one window (train rows cluster, val rows rank groups). Returns (feats, tuned, info)."""
    fset = set(cfi_factors)
    facs = [f for f in features if f in fset]
    bic, _, btrees, bm = base
    pf = lambda X: bm.predict(X, iteration_range=(0, btrees))
    clusters, cands, seen = cfi_clusters(tr, facs, cfg), [], set()
    for cut, groups in clusters.items():
        imps = cfi_importance(pf, va, features, groups, cfg)
        for share in cfg["cfi_shares"]:
            sub = cfi_candidates(groups, imps, [share])[0]
            key = frozenset(sub)
            if key in seen:
                continue
            seen.add(key)
            sel = [f for f in features if f in key or f not in fset]
            t = _rk_tune(tr, va, sel, cfg, ytr, yva)
            cands.append(dict(name=f"cut{cut:.2f}_top{round(share * 100)}", n_factors=len(key), val_ic=t[0], feats=sel, tuned=t))
    best = None
    for c in cands:  # strictly better IC wins; exact ties -> fewer features
        if np.isfinite(c["val_ic"]) and (best is None or (c["val_ic"], -c["n_factors"]) > (best["val_ic"], -best["n_factors"])):
            best = c
    use = best is not None and (not np.isfinite(bic) or best["val_ic"] > bic)
    info = dict(chosen=best["name"] if use else "all", n_factors=best["n_factors"] if use else len(facs),
                val_ic_base=bic, val_ic_chosen=best["val_ic"] if use else bic,
                candidates=[dict(name=c["name"], n_factors=c["n_factors"], val_ic=c["val_ic"]) for c in cands])
    return (best["feats"], best["tuned"], info) if use else (features, base, info)


def fit_predict_year(df, features, win, cfg, model="xgb", shuffle=False, cfi_factors=None):
    """Tune on val (train-only fits), refit on train+val, predict the test year. Returns (test_pred, val_pred, info)."""
    df = df.sort(["eom", "permno"])
    rng = lambda w: (pl.col("target_month") >= w[0]) & (pl.col("target_month") <= w[1])
    has_y = pl.col("ret_exc_lead1m").is_not_null()
    tr, va = df.filter(rng(win["train"]) & has_y), df.filter(rng(win["val"]) & has_y)
    te = df.filter(rng(win["test"]))
    va_all = df.filter(rng(win["val"]))  # incl. null-target rows: val_pred must cover every validation month-row
    ytr, yva = tr["ret_exc_lead1m"].to_numpy(), va["ret_exc_lead1m"].to_numpy()
    if shuffle:  # leakage test: destroy the label-feature link in train AND val
        ytr, yva = _rk_shuffle(tr["eom"], ytr, cfg["seed"]), _rk_shuffle(va["eom"], yva, cfg["seed"] + 1)
    cfi_info = None
    if model == "xgb":
        grid = {}
        tuned = _rk_tune(tr, va, features, cfg, ytr, yva, grid)
        if cfi_factors is not None and cfg.get("cfi_enabled"):
            features, tuned, cfi_info = _rk_cfi_select(tr, va, features, cfg, ytr, yva, tuned, cfi_factors)
    Xtr, Xva, Xte = _rk_mat(tr, features), _rk_mat(va, features), _rk_mat(te, features)
    Xall, yall = np.vstack([Xtr, Xva]), np.concatenate([ytr, yva])
    eall = pl.concat([tr["eom"], va["eom"]])

    if model == "xgb":
        best, best_m = tuned[:3], tuned[3]
        val_score = best_m.predict(Xva, iteration_range=(0, best[2]))
        final = _rk_xgb(cfg, best[1], best[2], Xall, yall, eall)
        te_score = final.predict(Xte)
        va_all_score = best_m.predict(_rk_mat(va_all, features), iteration_range=(0, best[2]))
    else:  # ridge baseline on the features (template: Ridge on the 147 characteristics)
        grid, best = {}, (-np.inf, None, None)
        Xtr0, Xva0, Xte0, Xall0 = (np.nan_to_num(x) for x in (Xtr, Xva, Xte, Xall))
        for a in cfg["ridge_alpha_grid"]:
            rm = Ridge(alpha=a).fit(Xtr0, ytr)
            s = rm.predict(Xva0)
            ic = _rk_mean_ic(va["eom"], s, yva)
            grid[str(a)] = ic
            if ic > best[0]:
                best, val_score, best_m = (ic, a, None), s, rm
        te_score = Ridge(alpha=best[1]).fit(Xall0, yall).predict(Xte0)
        va_all_score = best_m.predict(np.nan_to_num(_rk_mat(va_all, features)))

    # ret_hat: linear regression of realised return on the within-month score rank, fitted on val scores of the train-only model
    slope, icpt = np.polyfit(_rk_ranks(va["eom"], val_score), yva, 1)
    out = lambda d, s: d.select("permno", "eom").with_columns(
        score=pl.Series(s, dtype=pl.Float64),
        ret_hat=pl.Series(icpt + slope * _rk_ranks(d["eom"], s), dtype=pl.Float64))
    info = dict(year=win["year"], model=model, best_depth=best[1] if model == "xgb" else None,
                best_trees=best[2], val_ic=best[0], grid=grid,
                train_max_target=max(tr["target_month"].max(), va["target_month"].max()))  # step 11 check
    if cfi_info is not None:
        info["cfi"], info["features"] = cfi_info, list(features)
    if model == "ridge":
        info["best_alpha"] = best[1]
    return out(te, te_score), out(va_all, va_all_score), info


def run_schedule(df, features, cfg, model="xgb", shuffle=False, return_vals=False, cfi_factors=None):
    """Loop over test years. Returns (preds, val_2021, infos); with return_vals a 4th value {year: that window's val_pred}."""
    tests, infos, val_2021, vals = [], [], None, {}
    for w in windows(cfg):
        t, v, i = fit_predict_year(df, features, w, cfg, model, shuffle, cfi_factors)
        tests.append(t); infos.append(i); vals[w["year"]] = v
        if w["year"] == 2021:
            val_2021 = v
    return (pl.concat(tests), val_2021, infos, vals) if return_vals else (pl.concat(tests), val_2021, infos)


# ===== src/risk.py =====
"""
src/risk.py - factor risk model (not in spec): monthly cross-sectional OLS factor returns on
[intercept, ranked characteristics, sector dummies]; F_t = trailing covariance of factor returns known at eom t.
"""
import numpy as np
import polars as pl


def risk_exposures(mdf, sectors, cfg):
    """One month -> n x k exposures: intercept, cfg risk_factors (nulls -> 0), sector dummies for `sectors`."""
    cols = mdf.select([pl.col(c).fill_nan(None).fill_null(0.0) for c in cfg["risk_factors"]]).to_numpy().astype(float)
    sec = mdf["sector"].fill_null("NA").to_numpy()
    D = (sec[:, None] == np.array(sectors)[None, :]).astype(float)
    return np.hstack([np.ones((len(mdf), 1)), cols, D])


def _risk_spec(res, t_frame, t, months, cfg):
    """Specific variance of the stocks listed in t_frame at t from residuals of `months` (known months <= t)."""
    r = res.filter(pl.col("eom").is_in(months)).group_by("permno").agg(
        pl.col("resid").var().alias("v"), pl.col("resid").count().alias("n"))
    r = r.with_columns(pl.when(pl.col("n") >= cfg["risk_spec_min"]).then(pl.col("v")).otherwise(None).alias("v"))
    out = t_frame.select("permno").join(r.select("permno", "v"), on="permno", how="left")
    med = out["v"].median()
    if med is None:                                         # nothing estimable: pooled residual variance
        med = res.filter(pl.col("eom").is_in(months))["resid"].var()
    return out.select("permno", pl.lit(t).cast(pl.Date).alias("eom"),
                      pl.col("v").fill_nan(None).fill_null(med).alias("spec_var"))


def risk_model(frame, cfg, market=None):
    """frame: permno, eom, sector, ret_exc_lead1m, risk factors ->
    {"sectors", "L": {eom: chol(F_t)}, "xs_vol": {eom: mean xs return std}, "spec": permno/eom/spec_var,
     "b": {eom: factor betas to S&P excess return} (only if `market` = eom, sp500_ret, tb3ms)}. Only f_s known <= t used."""
    sectors = sorted(frame["sector"].fill_null("NA").unique().to_list())
    fs, vol, res = {}, {}, []                                               # eom s -> factor return realised in month s+1
    for (s,), g in frame.filter(pl.col("ret_exc_lead1m").is_not_null()).sort("eom").group_by("eom", maintain_order=True):
        X = risk_exposures(g, sectors, cfg)
        y = g["ret_exc_lead1m"].to_numpy().astype(float)
        fs[s] = np.linalg.lstsq(X, y, rcond=None)[0]
        vol[s] = y.std(ddof=1)
        res.append(pl.DataFrame({"permno": g["permno"], "eom": pl.Series([s] * len(y), dtype=pl.Date), "resid": y - X @ fs[s]}))
    eoms = sorted(fs)
    known = dict(zip(eoms, pl.Series(eoms).dt.offset_by("1mo").dt.month_end().to_list()))   # f_s known at eom s+1
    res = pl.concat(res)
    mk = {} if market is None else {e: r - b / 1200 for e, r, b in market.select("eom", "sp500_ret", "tb3ms").drop_nulls().iter_rows()}
    L, xs_vol, spec, b = {}, {}, [], {}
    for t in sorted(frame["eom"].unique().to_list()):
        kn = [s for s in eoms if known[s] <= t]
        past = [fs[s] for s in kn][-cfg["risk_window"]:]
        if kn:
            spec.append(_risk_spec(res, frame.filter(pl.col("eom") == t), t, kn[-cfg["risk_spec_window"]:], cfg))
        if len(past) < cfg["risk_min_months"]:
            continue
        xs_vol[t] = float(np.mean([vol[s] for s in kn[-cfg["risk_window"]:]]))
        F = np.cov(np.array(past), rowvar=False)
        k = F.shape[0]                                     # few months vs ~22 factors: shrink toward avg variance
        F = 0.9 * F + 0.1 * np.trace(F) / k * np.eye(k) + 1e-8 * np.eye(k)
        L[t] = np.linalg.cholesky(F)
        ks = [s for s in kn[-cfg["risk_window"]:] if known[s] in mk]
        if market is not None and len(ks) >= cfg["risk_min_months"]:
            m = np.array([mk[known[s]] for s in ks])
            m = m - m.mean()
            b[t] = (m @ (np.array([fs[s] for s in ks]) - np.mean([fs[s] for s in ks], axis=0))) / (m @ m)
    out = {"sectors": sectors, "L": L, "xs_vol": xs_vol, "spec": pl.concat(spec)}
    if market is not None:
        out["b"] = b
    return out


def _risk_midx(col):
    """Date column -> integer calendar-month index (year*12 + month-1)."""
    return col.dt.year().cast(pl.Int64) * 12 + col.dt.month().cast(pl.Int64) - 1


def lw_factor(rets, eom, window, permnos):
    """Ledoit-Wolf factor form (port of the teammate's ledoit_wolf_factor): Sigma = (1-delta)*Xc'Xc/T + delta*mu*I.
    rets: pl.DataFrame[permno, eom, ret] (monthly returns, all stocks). Uses months eom-window+1..eom only, and only
    `permnos` with `window` consecutive finite returns (full_history_mask). -> dict(Xc, delta, mu, T, permnos)."""
    from sklearn.covariance import ledoit_wolf_shrinkage
    m1 = eom.year * 12 + eom.month - 1
    m0 = m1 - window + 1
    pm = np.unique(np.asarray(list(permnos), dtype=np.int64))
    if "_m" not in rets.columns:
        rets = rets.with_columns(_m=_risk_midx(pl.col("eom")))
    sub = rets.filter((pl.col("_m") >= m0) & (pl.col("_m") <= m1) & pl.col("permno").is_in(pm.tolist()))
    X = np.full((window, len(pm)), np.nan)
    if len(sub):
        X[sub["_m"].to_numpy() - m0, np.searchsorted(pm, sub["permno"].to_numpy())] = sub["ret"].to_numpy().astype(float)
    ok = np.isfinite(X).all(axis=0)
    X, pm = X[:, ok], pm[ok]
    if X.shape[1] == 0:
        return {"Xc": X, "delta": 0.0, "mu": 0.0, "T": window, "permnos": pm}
    Xc = X - X.mean(axis=0)
    delta = float(ledoit_wolf_shrinkage(X, assume_centered=False))
    mu = float((Xc ** 2).sum() / (X.shape[0] * X.shape[1]))
    return {"Xc": Xc, "delta": delta, "mu": mu, "T": window, "permnos": pm}


def _risk_variance(fac, w, idx):
    """Ex-ante variance w' Sigma w for weights w on factor columns idx."""
    x = fac["Xc"][:, idx] @ w
    return float((1 - fac["delta"]) / fac["T"] * (x @ x) + fac["delta"] * fac["mu"] * (w @ w))


# ===== src/optimizer.py =====
"""
src/optimizer.py - Step 9: long/short portfolio optimiser (cvxpy + Clarabel), one convex problem per month.
w = wL - wS over the UNION of long candidates (top n by score) and short candidates (bottom n of the short-eligible subset).
"""
import cvxpy as cp
import numpy as np
import polars as pl


def optimize_month(mdf, w_prev, lam_tc, lam_beta, cfg, lam_risk=0.0, lam_fac=0.0, risk=None):
    """mdf: one month with permno, score, short_eligible, beta_kf, beta_var, sector [, size_z] -> (weights dict, info dict); risk = (sectors, L) adds lam_fac * w'X F X'w."""
    d = mdf.with_columns(pl.col("sector").fill_null("NA")).sort("permno").with_columns(
        ((pl.col("score") - pl.col("score").mean()) / pl.col("score").std()).fill_nan(0.0).fill_null(0.0).alias("s"),
        pl.col("beta_kf").fill_nan(None).fill_null(pl.col("beta_kf").median()),
        pl.col("beta_var").fill_nan(None).fill_null(pl.col("beta_var").median()))
    has_size = "size_z" in d.columns                                       # not in spec: size neutrality only if present
    if has_size:
        d = d.with_columns(pl.col("size_z").fill_nan(None).fill_null(0.0))
    long_ids = set(d.sort(["s", "permno"], descending=[True, False]).head(cfg["n_long_cand"])["permno"])
    short_ids = set(d.filter(pl.col("short_eligible") & ~pl.col("permno").is_in(long_ids))     # no name on both sides:
                    .sort(["s", "permno"]).head(cfg["n_short_cand"])["permno"])               # wL=wS would fake gross
    c = d.filter(pl.col("permno").is_in(long_ids | short_ids))
    ids = c["permno"].to_list(); n = len(ids)
    s, bk, bv = c["s"].to_numpy(), c["beta_kf"].to_numpy(), c["beta_var"].to_numpy()
    sz = c["size_z"].to_numpy() if has_size else None
    ubL = np.array([cfg["max_weight"] if p in long_ids else 0.0 for p in ids])
    ubS = np.array([cfg["max_weight"] if p in short_ids else 0.0 for p in ids])
    G = (c["sector"].to_numpy()[None, :] == np.unique(c["sector"].to_numpy())[:, None]).astype(float)
    wp = np.clip(np.nan_to_num(np.array([w_prev.get(p, 0.0) for p in ids])), -cfg["max_weight"], cfg["max_weight"])
    dropped = sum(abs(v) for p, v in w_prev.items() if p not in set(ids))   # names that left the candidate set: sold to 0

    wL, wS = cp.Variable(n, nonneg=True), cp.Variable(n, nonneg=True)
    tol, band, sband = cp.Parameter(nonneg=True), cp.Parameter(nonneg=True), cp.Parameter(nonneg=True)
    w = wL - wS
    obj = s @ w - lam_tc * cp.norm1(w - wp) - lam_beta * (bv @ cp.square(w)) - lam_risk * cp.sum_squares(w)   # L2 risk penalty (not in spec); dropped-name sales are a constant
    cons = [cp.sum(wL) + cp.sum(wS) == cfg["gross"], cp.abs(cp.sum(w)) <= cfg["net_band"], wL <= ubL, wS <= ubS,
            cp.abs(bk @ w) <= tol, cp.abs(G @ w) <= band]
    if has_size:
        cons.append(cp.abs(sz @ w) <= sband)                               # not in spec: size-neutral book
    if lam_fac > 0 and risk is not None:
        obj = obj - lam_fac * cp.sum_squares(risk[1].T @ (risk_exposures(c, risk[0], cfg).T @ w))   # factor-risk penalty (not in spec)
    prob = cp.Problem(cp.Maximize(obj), cons)

    def solve(t_, b_, sb_):
        tol.value, band.value, sband.value = t_, b_, sb_
        try:
            prob.solve(solver=cp.CLARABEL)
        except cp.SolverError:
            return False                                                   # treated as a failed attempt
        if prob.status not in (cp.OPTIMAL, cp.OPTIMAL_INACCURATE) or w.value is None:
            return False
        v = w.value                                                        # inaccurate solutions can hold garbage weights
        return bool(np.all(np.isfinite(v)) and np.abs(v).max() <= cfg["max_weight"] + 1e-4
                    and abs(np.abs(v).sum() - cfg["gross"]) <= 1e-3)

    t, b, sb, no_beta = cfg["beta_tol"], cfg["sector_band"], cfg["size_band"], 1e6
    if not solve(t, b, sb):
        # Not in spec: if the month is infeasible even with NO beta limit, the sector nets bind,
        # so widen the sector (and size) band in 0.05 steps first (logged), then relax beta from 0.02 as the spec says.
        while not solve(no_beta, b, sb):
            b += 0.05
            sb += 0.05
            if b > 2.0:                                                    # should not happen: save inputs, hold last book
                eom = mdf["eom"][0]
                path = cfg["cache_dir"] / f"optimizer_fail_{eom}.parquet"
                mdf.write_parquet(path)
                bad = {k: int((~np.isfinite(v)).sum()) for k, v in (("s", s), ("beta_kf", bk), ("beta_var", bv))}
                print(f"[optimizer] WARNING {eom}: infeasible ({prob.status}) even with sector band 2.0 and no beta limit; "
                      f"rows={d.height} long_cand={len(long_ids)} short_cand={len(short_ids)} non-finite={bad}; "
                      f"holding previous weights; inputs saved to {path}")
                return dict(w_prev), {"beta_tol": None, "sector_band": b, "size_band": sb, "status": "fallback_hold",
                                      "n_long": sum(v > 0 for v in w_prev.values()),
                                      "n_short": sum(v < 0 for v in w_prev.values()), "turnover": 0.0}
        while not solve(t, b, sb):                                           # spec: relax beta tolerance in 0.01 steps
            t += cfg["beta_tol_step"]                                      # terminates: feasible without a beta limit
    wv = np.where(np.abs(w.value) < 1e-7, 0.0, w.value)
    weights = {p: float(x) for p, x in zip(ids, wv) if x != 0.0}
    turnover = float(np.abs(wv - wp).sum() + dropped)
    return weights, {"beta_tol": round(t, 6), "sector_band": round(b, 6), "size_band": round(sb, 6), "status": prob.status, "n_long": int((wv > 0).sum()),
                     "n_short": int((wv < 0).sum()), "turnover": turnover}


def run_book(scored, lam_tc, lam_beta, cfg, lam_risk=0.0, lam_fac=0.0, rm=None):
    """scored: all months (permno, eom, score, short_eligible, beta_kf, beta_var, sector) -> (weights df, log)."""
    w_prev, rows, log = {}, [], []
    for (eom,), mdf in scored.sort("eom").group_by("eom", maintain_order=True):
        risk = (rm["sectors"], rm["L"][eom]) if rm is not None and eom in rm["L"] else None
        w, info = optimize_month(mdf, w_prev, lam_tc, lam_beta, cfg, lam_risk, lam_fac, risk)
        if info["beta_tol"] is not None and info["beta_tol"] > cfg["beta_tol"]:
            print(f"[optimizer] {eom}: beta tolerance relaxed to {info['beta_tol']:.2f}")
        if info["sector_band"] > cfg["sector_band"]:
            print(f"[optimizer] {eom}: sector band relaxed to {info['sector_band']:.2f} (infeasible at 0.10)")
        if info["size_band"] > cfg["size_band"]:
            print(f"[optimizer] {eom}: size band relaxed to {info['size_band']:.2f}")
        log.append({"eom": eom, **info})
        rows += [(p, eom, x) for p, x in w.items()]
        w_prev = w
    wdf = pl.DataFrame(rows, schema={"permno": pl.Int64, "eom": pl.Date, "weight": pl.Float64}, orient="row")
    return wdf, log


def _opt_ladder(cfg):
    """Relaxation steps (sector/size band, beta tol, vol multiplier): bands first, then beta, then vol (each stage keeps earlier relaxations)."""
    b0, s0, t0 = cfg["sector_band"], cfg["size_band"], cfg["v2_beta_tol"]
    steps = [(b0, s0, t0, 1.0)]
    b, s = b0, s0
    for _ in range(9):
        b, s = b + 0.05, s + 0.05
        steps.append((b, s, t0, 1.0))
    t = t0
    for _ in range(int(round((0.5 - t0) / 0.01))):
        t += 0.01
        steps.append((b, s, t, 1.0))
    m = 1.0
    while m < 4.0 - 1e-9:
        m = min(m * 1.25, 4.0)
        steps.append((b, s, t, m))
    return steps


def optimize_month_v2(mdf, w_prev, cfg, risk, ic):
    """One month -> (weights dict, info dict). Max alpha.w - v2_cost*|w - w_prev|_1 s.t. gross/net/sector/size/beta/ex-ante vol caps.
    risk = (sectors, L, b, xs_vol); alpha = max(ic, floor) * xs_vol * z (monthly expected excess return). L None -> vol constraint off."""
    sectors, L, b_vec, xs_vol = risk
    cap = cfg["v2_max_weight"]
    d = mdf.with_columns(pl.col("sector").fill_null("NA")).sort("permno").with_columns(
        ((pl.col("score") - pl.col("score").mean()) / pl.col("score").std()).fill_nan(0.0).fill_null(0.0).alias("s"),
        pl.col("spec_var").fill_nan(None).fill_null(pl.col("spec_var").median()).fill_null(0.0).clip(lower_bound=0.0),
        pl.col("size_z").fill_nan(None).fill_null(0.0))
    long_ids = set(d.sort(["s", "permno"], descending=[True, False]).head(cfg["n_long_cand"])["permno"])
    short_ids = set(d.filter(pl.col("short_eligible") & ~pl.col("permno").is_in(long_ids))
                    .sort(["s", "permno"]).head(cfg["n_short_cand"])["permno"])
    c = d.filter(pl.col("permno").is_in(long_ids | short_ids))
    ids = c["permno"].to_list(); n = len(ids)
    alpha = max(ic, cfg["v2_ic_floor"]) * xs_vol * c["s"].to_numpy()
    sz, spec = c["size_z"].to_numpy(), np.sqrt(c["spec_var"].to_numpy())
    ubL = np.array([cap if p in long_ids else 0.0 for p in ids])
    ubS = np.array([cap if p in short_ids else 0.0 for p in ids])
    G = (c["sector"].to_numpy()[None, :] == np.unique(c["sector"].to_numpy())[:, None]).astype(float)
    X = risk_exposures(c, sectors, cfg) if (L is not None or b_vec is not None) else None
    if b_vec is not None:
        beta = X @ np.asarray(b_vec, dtype=float)
    elif "beta_kf" in c.columns:
        beta = c["beta_kf"].fill_nan(None).fill_null(0.0).to_numpy()
    else:
        beta = None
    LtXt = L.T @ X.T if L is not None else None
    wp = np.clip(np.nan_to_num(np.array([w_prev.get(p, 0.0) for p in ids])), -cap, cap)
    dropped = sum(abs(v) for p, v in w_prev.items() if p not in set(ids))   # names that left the candidate set: sold to 0

    wL, wS = cp.Variable(n, nonneg=True), cp.Variable(n, nonneg=True)
    band, sband, tol, vol = (cp.Parameter(nonneg=True) for _ in range(4))
    w = wL - wS
    cons = [cp.sum(wL) + cp.sum(wS) <= cfg["gross"], cp.abs(cp.sum(w)) <= cfg["net_band"], wL <= ubL, wS <= ubS,
            cp.abs(G @ w) <= band, cp.abs(sz @ w) <= sband]
    if beta is not None:
        cons.append(cp.abs(beta @ w) <= tol)
    if LtXt is not None:
        cons.append(cp.norm(cp.hstack([LtXt @ w, cp.multiply(spec, w)])) <= vol)
    prob = cp.Problem(cp.Maximize(alpha @ w - cfg["v2_cost"] * cp.norm1(w - wp)), cons)
    vol0 = cfg["v2_vol_target"] / np.sqrt(12)

    def solve(bd, sb, t_, vm):
        band.value, sband.value, tol.value, vol.value = bd, sb, t_, vol0 * vm
        try:
            prob.solve(solver=cp.CLARABEL)
        except cp.SolverError:
            return False
        if prob.status not in (cp.OPTIMAL, cp.OPTIMAL_INACCURATE) or w.value is None:
            return False
        v = w.value
        return bool(np.all(np.isfinite(v)) and np.abs(v).max() <= cap + 1e-4 and np.abs(v).sum() <= cfg["gross"] + 1e-3
                    and abs(v.sum()) <= cfg["net_band"] + 1e-3)                  # inaccurate solutions must still obey net

    for bd, sb, t_, vm in _opt_ladder(cfg):
        if solve(bd, sb, t_, vm):
            break
    else:
        print(f"[optimizer-v2] WARNING {mdf['eom'][0]}: infeasible even after full relaxation; holding previous weights")
        return dict(w_prev), {"status": "fallback_hold", "n_long": sum(v > 0 for v in w_prev.values()),
                              "n_short": sum(v < 0 for v in w_prev.values()), "gross": float(sum(abs(v) for v in w_prev.values())),
                              "net": float(sum(w_prev.values())), "turnover": 0.0, "vol": None, "beta_pred": None, "relaxed": ["hold"]}
    wv = np.where(np.abs(w.value) < 1e-7, 0.0, w.value)
    relaxed = []
    if bd > cfg["sector_band"] + 1e-9:
        relaxed.append(f"sector/size band {bd:.2f}/{sb:.2f}")
    if beta is not None and t_ > cfg["v2_beta_tol"] + 1e-9:
        relaxed.append(f"beta tol {t_:.2f}")
    if vm > 1.0 + 1e-9:
        relaxed.append(f"vol target x{vm:.2f}")
    var = float(np.sum((LtXt @ wv) ** 2) + np.sum((spec * wv) ** 2)) if LtXt is not None else None
    weights = {p: float(x) for p, x in zip(ids, wv) if x != 0.0}
    return weights, {"status": prob.status, "n_long": int((wv > 0).sum()), "n_short": int((wv < 0).sum()),
                     "gross": float(np.abs(wv).sum()), "net": float(wv.sum()), "turnover": float(np.abs(wv - wp).sum() + dropped),
                     "vol": float(np.sqrt(12 * var)) if var is not None else None,
                     "beta_pred": float(beta @ wv) if beta is not None else None, "relaxed": relaxed}


def run_book_v2(scored, cfg, rm, ic):
    """scored: all months -> (weights df, log). ic: float or dict eom -> float; rm: risk model dict (sectors, L, xs_vol, optional b)."""
    w_prev, rows, log = {}, [], []
    for (eom,), mdf in scored.sort("eom").group_by("eom", maintain_order=True):
        if eom in rm["L"] and eom in rm["xs_vol"]:
            risk = (rm["sectors"], rm["L"][eom], rm.get("b", {}).get(eom), rm["xs_vol"][eom])
        else:
            print(f"[optimizer-v2] WARNING {eom}: no risk model, vol constraint off")
            risk = (rm["sectors"], None, None, rm["xs_vol"].get(eom, 0.0))
        w, info = optimize_month_v2(mdf, w_prev, cfg, risk, ic[eom] if isinstance(ic, dict) else ic)
        if info["relaxed"]:
            print(f"[optimizer-v2] {eom}: relaxed {', '.join(info['relaxed'])}")
        log.append({"eom": eom, **info})
        rows += [(p, eom, x) for p, x in w.items()]
        w_prev = w
    wdf = pl.DataFrame(rows, schema={"permno": pl.Int64, "eom": pl.Date, "weight": pl.Float64}, orient="row")
    return wdf, log


def _opt_cap(w, cap, total):
    """Scale positive array w to sum `total`, cap each at `cap`, redistribute the excess to uncapped names. -> (w, capped?)"""
    w = w / w.sum() * total
    capped = False
    for _ in range(50):
        over = w > cap + 1e-12
        if not over.any():
            break
        capped = True
        w = np.where(over, cap, w)
        free = ~over & (w < cap - 1e-12)
        if not free.any() or total - w[~free].sum() <= 0:
            break
        w[free] *= (total - w[~free].sum()) / w[free].sum()
    return w, capped


def run_book_v3(scored, cfg, smooth):
    """Sector-neutral equal-weight tail book on smoothed z-scores, beta-neutral legs. scored: permno, eom, score, short_eligible,
    sector, beta_kf -> (weights df[permno, eom, weight], log list of dicts)."""
    prev_s, w_prev, rows, log = {}, {}, [], []
    for (eom,), mdf in scored.sort("eom").group_by("eom", maintain_order=True):
        sc = mdf["score"].to_numpy().astype(float)
        sc = np.where(np.isfinite(sc), sc, np.nan)
        sd = np.nanstd(sc, ddof=1) if np.isfinite(sc).sum() > 1 else 0.0
        z = np.nan_to_num((sc - np.nanmean(sc)) / sd) if sd > 0 else np.zeros(len(sc))
        pm = mdf["permno"].to_list()
        s = np.array([smooth * zi + (1 - smooth) * prev_s.get(p, zi) for p, zi in zip(pm, z)])
        prev_s = dict(zip(pm, s))
        beta = mdf["beta_kf"].to_numpy().astype(float)
        beta = np.where(np.isfinite(beta), beta, np.nanmedian(beta) if np.isfinite(beta).any() else 1.0)
        elig = mdf["short_eligible"].fill_null(False).to_numpy()
        sec = np.array(mdf["sector"].fill_null("NA").cast(pl.Utf8).to_list())
        tail = cfg["v3_tail"]
        while True:                               # competition rule: <= 500 names -> shrink the tail until it fits
            longs, shorts, budget = [], [], []    # per kept sector: index arrays + stock count
            for sname in np.unique(sec):
                idx = np.where(sec == sname)[0]
                nl = int(np.ceil(tail * len(idx)))
                top = idx[np.argsort(-s[idx], kind="stable")[:nl]]
                cand = idx[elig[idx] & ~np.isin(idx, top)]
                ns = int(np.ceil(tail * elig[idx].sum()))
                bot = cand[np.argsort(s[cand], kind="stable")[:ns]]
                if len(top) and len(bot):
                    longs.append(top); shorts.append(bot); budget.append(len(idx))
            if sum(len(x) for x in longs + shorts) <= 500 or tail <= 0.02:
                break
            tail -= 0.01
        flags = []
        if not longs:
            log.append({"eom": eom, "n_long": 0, "n_short": 0, "gross": 0.0, "net": 0.0, "beta_exposure": 0.0, "turnover": sum(abs(x) for x in w_prev.values()), "flags": ["empty"]})
            w_prev = {}
            continue
        budget = np.array(budget, float) / sum(budget)
        li, si = np.concatenate(longs), np.concatenate(shorts)
        lw = np.concatenate([np.full(len(a), b / len(a)) for a, b in zip(longs, budget)])
        sw = np.concatenate([np.full(len(a), b / len(a)) for a, b in zip(shorts, budget)])
        bl, bs = float(lw @ beta[li]), float(sw @ beta[si])
        g = cfg["gross"]
        L = g * bs / (bl + bs) if bl + bs > 1e-9 else g / 2
        if abs(2 * L - g) > cfg["net_band"]:
            L = (g + np.sign(2 * L - g) * cfg["net_band"]) / 2
            flags.append("net_clipped")
        S = g - L
        lw, c1 = _opt_cap(lw, cfg["max_weight"], L)
        sw, c2 = _opt_cap(sw, cfg["max_weight"], S)
        if c1 or c2:
            flags.append("max_weight_capped")
        n_names = len(li) + len(si)
        if n_names > 500:
            flags.append("names_gt_500")
            print(f"[optimizer-v3] {eom}: {n_names} names > 500")
        w = {int(pm[i]): float(x) for i, x in zip(li, lw)}
        w.update({int(pm[i]): -float(x) for i, x in zip(si, sw)})
        turn = sum(abs(w.get(p, 0.0) - w_prev.get(p, 0.0)) for p in set(w) | set(w_prev))
        log.append({"eom": eom, "n_long": len(li), "n_short": len(si), "gross": float(lw.sum() + sw.sum()), "net": float(lw.sum() - sw.sum()),
                    "beta_exposure": float(lw @ beta[li] - sw @ beta[si]), "turnover": float(turn), "flags": flags})
        rows += [(p, eom, x) for p, x in w.items()]
        w_prev = w
    wdf = pl.DataFrame(rows, schema={"permno": pl.Int64, "eom": pl.Date, "weight": pl.Float64}, orient="row")
    return wdf, log


# ---------------------------------------------------------------------------------------------------------------
# book v4: port of the teammate's convex construction (portfolio.py), Ledoit-Wolf risk, Clarabel
# ---------------------------------------------------------------------------------------------------------------
def _opt_pred_scores(s):
    """Teammate's prediction_scores: 2*avg_rank/(N+1)-1 over all finite scores of the month."""
    from scipy.stats import rankdata
    return 2.0 * rankdata(s, method="average") / (len(s) + 1.0) - 1.0


def _opt_main_lists(permno, s, short_ok, per_side):
    """Attempt 1: top per_side by score long, then bottom per_side among short-eligible of the rest (disjoint).
    Ties: permno ascending. Returns index arrays."""
    order = np.lexsort((permno, -s))
    longs = order[:per_side]
    rest = np.setdiff1d(np.where(short_ok)[0], longs)
    shorts = rest[np.lexsort((permno[rest], s[rest]))][:per_side]
    return longs, shorts


def _opt_fallback_lists(permno, s, short_ok, grp, per_group_max):
    """Attempt 2: per size group of n names, k = min(per_group_max, n//2) best long and k worst (short-eligible) short."""
    longs, shorts = [], []
    for g in np.unique(grp):
        mem = np.where(grp == g)[0]
        k = min(per_group_max, len(mem) // 2)
        if k == 0:
            continue
        top = mem[np.lexsort((permno[mem], -s[mem]))][:k]
        rest = np.setdiff1d(mem[short_ok[mem]], top)
        bot = rest[np.lexsort((permno[rest], s[rest]))][:k]
        longs += list(top)
        shorts += list(bot)
    return np.array(longs, dtype=int), np.array(shorts, dtype=int)


def _opt_solve_v4(longs, shorts, s, beta, grp, fac, fidx, wb, p, cfg):
    """One convex solve on the given lists. Returns (weights over longs+shorts or None, status)."""
    n_l, n = len(longs), len(longs) + len(shorts)
    if len(longs) == 0 or len(shorts) == 0:
        return None, "empty_side"
    ix = np.r_[longs, shorts]
    G = p["gross"]
    Xc = fac["Xc"][:, fidx[ix]]
    w, t = cp.Variable(n), cp.Variable(n)
    risk = (1 - fac["delta"]) / fac["T"] * cp.sum_squares(Xc @ w) + fac["delta"] * fac["mu"] * cp.sum_squares(w)
    obj = cp.Maximize(s[ix] @ w - p["risk_penalty"] * risk - p["turnover_penalty"] * cp.sum(t))
    cons = [w[:n_l] >= 0, w[n_l:] <= 0, cp.sum(w[:n_l]) == G / 2, cp.sum(w[n_l:]) == -G / 2,
            beta[ix] @ w <= cfg["v4_beta_limit"], beta[ix] @ w >= -cfg["v4_beta_limit"], t >= w - wb[ix], t >= wb[ix] - w]
    gi = grp[ix]
    tol = cfg["v4_size_balance"] * G / 2
    for g in np.unique(gi):
        m = (gi == g).astype(float)
        cons += [m @ w <= tol, m @ w >= -tol]
    prob = cp.Problem(obj, cons)
    try:
        prob.solve(solver=cp.CLARABEL)
    except cp.error.SolverError:
        return None, "solver_error"
    if prob.status != cp.OPTIMAL or w.value is None:
        return None, str(prob.status)
    x = np.where(np.abs(w.value) < 1e-7, 0.0, w.value)       # numeric cleaning, then each side back to exactly G/2
    x[:n_l], x[n_l:] = np.maximum(x[:n_l], 0.0), np.minimum(x[n_l:], 0.0)
    if x[:n_l].sum() > 0:
        x[:n_l] *= G / 2 / x[:n_l].sum()
    if x[n_l:].sum() < 0:
        x[n_l:] *= -G / 2 / x[n_l:].sum()
    return x, "optimal"


def _opt_valid_v4(x, ix, beta, grp, p, cfg):
    """Teammate's check_portfolio on the final weights; returns list of failed rules."""
    G, tol = p["gross"], 1e-4
    n_l, n_s = int((x > 0).sum()), int((x < 0).sum())
    n = n_l + n_s
    if not np.isfinite(x).all():
        return ["nan"]
    bad = []
    if not (cfg["v4_min_names"] <= n <= cfg["v4_max_names"]):
        bad.append("names")
    if n and not (cfg["v4_long_share"][0] <= n_l / n <= cfg["v4_long_share"][1]):
        bad.append("long_share")
    if abs(x.sum()) > tol or abs(np.abs(x).sum() - G) > tol:
        bad.append("net_gross")
    if abs(beta[ix] @ x) > cfg["v4_beta_limit"] + tol:
        bad.append("beta")
    gi = grp[ix]
    for g in np.unique(gi):
        m = gi == g
        if abs(x[m & (x > 0)].sum() / (G / 2) - (-x[m & (x < 0)].sum()) / (G / 2)) > cfg["v4_size_balance"] + tol:
            bad.append(f"size_{g}")
    return bad


def run_book_v4(scored, cfg, params_by_eom, rets):
    """Teammate's convex book on our universe. scored: permno, eom, score, short_eligible, beta_60m_raw, size_grp;
    params_by_eom: eom -> {gross, cov_window, risk_penalty, turnover_penalty}; rets: [permno, eom, ret] monthly panel.
    -> (weights df[permno, eom, weight], log list). Attempt 1 main lists, 2 size-group fallback, else hold previous."""
    rets = rets.with_columns(_m=_risk_midx(pl.col("eom")))
    w_prev, rows, log = {}, [], []
    for (eom,), mdf in scored.sort("eom").group_by("eom", maintain_order=True):
        p = params_by_eom[eom]
        sc = mdf["score"].to_numpy().astype(float)
        finite = np.isfinite(sc)
        mdf, sc = mdf.filter(pl.Series(finite)), sc[finite]
        ok = (mdf["beta_60m_raw"].is_not_null() & mdf["beta_60m_raw"].is_not_nan() & mdf["size_grp"].is_not_null()).to_numpy()
        mdf, sc = mdf.filter(pl.Series(ok)), sc[ok]                     # eligible set only (as teammate's lw fit)
        s_all = _opt_pred_scores(sc) if len(sc) else sc
        fac = lw_factor(rets, eom, int(p["cov_window"]), mdf["permno"].to_numpy())
        pm_all = mdf["permno"].to_numpy().astype(np.int64)
        beta_all = mdf["beta_60m_raw"].to_numpy().astype(float)
        grp_all = np.array(mdf["size_grp"].cast(pl.Utf8).fill_null("NA").to_list())
        keep = np.isin(pm_all, fac["permnos"]) & np.isfinite(beta_all) & (grp_all != "NA")
        pm, s, beta, grp = pm_all[keep], s_all[keep], beta_all[keep], grp_all[keep]
        short_ok = mdf["short_eligible"].fill_null(False).to_numpy()[keep]
        fidx = np.searchsorted(fac["permnos"], pm)                       # factor columns (permnos sorted)
        wb = np.array([w_prev.get(int(q), 0.0) for q in pm])
        w, ix, status, attempt = None, None, "no_candidates", None
        for attempt, lists in (("main", lambda: _opt_main_lists(pm, s, short_ok, cfg["v4_per_side"])),
                               ("fallback", lambda: _opt_fallback_lists(pm, s, short_ok, grp, 50))):
            lo, sh = lists()
            x, status = _opt_solve_v4(lo, sh, s, beta, grp, fac, fidx, wb, p, cfg)
            if x is None:
                continue
            ix_try = np.r_[lo, sh]
            bad = _opt_valid_v4(x, ix_try, beta, grp, p, cfg)
            if bad:
                status = "failed:" + ",".join(bad)
                continue
            w, ix = x, ix_try
            break
        if w is None:                                                     # last resort: hold previous weights
            new = dict(w_prev)
            status, attempt = f"hold_prev({status})", "hold"
            print(f"[optimizer-v4] {eom}: {status}")
        else:
            new = {int(pm[i]): float(x_) for i, x_ in zip(ix, w) if x_ != 0}
        bmap = dict(zip(pm.tolist(), beta.tolist()))
        bv = sum(v * bmap.get(q, 0.0) for q, v in new.items())
        turn = sum(abs(new.get(q, 0.0) - w_prev.get(q, 0.0)) for q in set(new) | set(w_prev))
        log.append({"eom": eom, "n_long": sum(v > 0 for v in new.values()), "n_short": sum(v < 0 for v in new.values()),
                    "gross": float(sum(abs(v) for v in new.values())), "net": float(sum(new.values())),
                    "beta_ex_ante": float(bv), "turnover": float(turn), "attempt": attempt, "status": status})
        rows += [(q, eom, v) for q, v in new.items()]
        w_prev = new
    return pl.DataFrame(rows, schema={"permno": pl.Int64, "eom": pl.Date, "weight": pl.Float64}, orient="row"), log


# ===== src/metrics.py =====
"""
src/metrics.py - Step 13 numbers: monthly book returns, summary statistics, OOS R2 and rank-IC summary.
Convention: weights at formation month-end t are realised with ret_exc_lead1m (excess return of month t+1).
"""
import numpy as np
import pandas as pd
import polars as pl
import statsmodels.api as sm


def load_market(cfg) -> pl.DataFrame:
    """TB3MS (annualised %) and S&P 500 monthly total return keyed on month-end eom."""
    f = cfg["data_files"]
    tb = pl.read_csv(f["tb3ms"], try_parse_dates=True).select(pl.col("eom").cast(pl.Date), "tb3ms")
    sp = pl.read_csv(f["sp500"], try_parse_dates=True).select(pl.col("eom").cast(pl.Date), "sp500_ret")
    return tb.join(sp, on="eom", how="full", coalesce=True).sort("eom")


def book_returns(weights, panel, market, cfg):
    """One row per formation month: returns, benchmark, legs, exposures, counts, turnover. Returns (rets, n_missing)."""
    w = weights.select("permno", "eom", "weight").join(
        panel.select("permno", "eom", "ret_exc_lead1m"), on=["permno", "eom"], how="left")
    n_missing = int(w["ret_exc_lead1m"].is_null().sum())
    w = w.with_columns(r=pl.col("ret_exc_lead1m").fill_null(0.0)).with_columns(c=pl.col("weight") * pl.col("r"))
    g = w.group_by("eom").agg(
        long_leg=pl.col("c").filter(pl.col("weight") > 0).sum(),
        short_leg=pl.col("c").filter(pl.col("weight") < 0).sum(),
        gross=pl.col("weight").abs().sum(), net=pl.col("weight").sum(),
        n_long=(pl.col("weight") > 0).sum(), n_short=(pl.col("weight") < 0).sum()).sort("eom")
    # turnover = sum |w_t - w_{t-1}| over the union of names (absent = 0); first month starts from cash
    pw = w.to_pandas().pivot_table(index="eom", columns="permno", values="weight", aggfunc="sum").sort_index().fillna(0.0)
    to = pw.diff().abs().sum(axis=1)
    if len(to):
        to.iloc[0] = pw.iloc[0].abs().sum()
    g = g.join(pl.DataFrame({"eom": pl.Series(to.index).cast(pl.Date), "turnover": to.values}), on="eom")
    mk = market.with_columns(eom=pl.col("eom").dt.offset_by("-1mo").dt.month_end()).select(  # key on formation month
        "eom", rf=pl.col("tb3ms") / 1200, sp500=pl.col("sp500_ret"))
    prem = cfg["premium_annual"] / 12
    rets = (g.join(mk, on="eom", how="left")
            .with_columns(Date=pl.col("eom").dt.offset_by("1mo").dt.month_start(),
                          excess=pl.col("long_leg") + pl.col("short_leg"))
            .with_columns(total=pl.col("rf") + pl.col("excess"), benchmark=pl.col("rf") + prem,
                          active=pl.col("excess") - prem)
            .select("eom", "Date", "total", "excess", "active", "long_leg", "short_leg", "benchmark", "sp500",
                    "gross", "net", "n_long", "n_short", "turnover", "rf"))
    return rets, n_missing


def _ir(a):
    sd = np.std(a, ddof=1)
    return float(np.sqrt(12) * np.mean(a) / sd) if sd > 0 else float("nan")


def _leg(r):
    """Arithmetic/geometric stats for one monthly return series."""
    n = len(r)
    cum = float(np.prod(1 + r) - 1)
    return {"mean_monthly": float(np.mean(r)), "ann_arith": float(np.mean(r) * 12),
            "cagr": float((1 + cum) ** (12 / n) - 1), "cumulative": cum}


def _mm(x):
    return {"avg": float(np.mean(x)), "min": float(np.min(x)), "max": float(np.max(x))}


def _maxdd(r):
    c = np.cumprod(1 + np.asarray(r))
    return float((c / np.maximum.accumulate(np.r_[1.0, c])[1:] - 1).min())


def summary_stats(rets, cfg) -> dict:
    """Headline statistics of the monthly book (see contract)."""
    d = rets.to_pandas()
    rf = d["rf"].values if "rf" in d else (d["benchmark"] - cfg["premium_annual"] / 12).values
    tot, exc, act, sp = d["total"].values, d["excess"].values, d["active"].values, d["sp500"].values
    sd_tot = np.std(tot - rf, ddof=1)
    out = {"n_months": len(d), "ir": _ir(act), "sharpe": float(np.sqrt(12) * np.mean(tot - rf) / sd_tot),
           "strategy": _leg(tot), "benchmark": _leg(d["benchmark"].values), "sp500": _leg(sp),
           "long_leg": _leg(d["long_leg"].values), "short_leg": _leg(d["short_leg"].values),
           "max_drawdown": _maxdd(tot), "sp500_max_drawdown": _maxdd(sp),
           "best_month": float(tot.max()), "worst_month": float(tot.min()),
           "hit_rate": float(np.mean((exc > 0) & (act > 0))),
           "gross": _mm(d["gross"]), "net": _mm(d["net"]), "turnover": _mm(d["turnover"]),
           "n_long": _mm(d["n_long"]), "n_short": _mm(d["n_short"]),
           "corr_sp500": float(np.corrcoef(tot, sp)[0, 1])}
    ols = sm.OLS(exc, sm.add_constant(sp - rf)).fit(cov_type="HAC", cov_kwds={"maxlags": cfg["nw_lags"]})
    out.update(alpha_monthly=float(ols.params[0]), alpha_annual=float(ols.params[0] * 12), alpha_t=float(ols.tvalues[0]),
               beta=float(ols.params[1]), beta_t=float(ols.tvalues[1]))
    yr = d["Date"].dt.year
    cal = lambda x: pd.Series(x).groupby(yr.values).apply(lambda s: float(np.prod(1 + s) - 1))
    out["calendar_years"] = {str(y): {"strategy": v, "benchmark": float(cal(d["benchmark"].values)[y]),
                                      "sp500": float(cal(sp)[y])} for y, v in cal(tot).items()}
    return out


def oos_r2(pred) -> float:
    """Zero-benchmark OOS R2 = 1 - sum (r - r_hat)^2 / sum r^2 on rows with non-null target."""
    p = pred.drop_nulls(["ret_exc_lead1m", "ret_hat"])
    r, h = p["ret_exc_lead1m"].to_numpy(), p["ret_hat"].to_numpy()
    return float(1 - np.sum((r - h) ** 2) / np.sum(r ** 2))


def ic_summary(pred, cfg) -> dict:
    """Mean monthly Spearman rank IC of score vs target, ICIR = mean/std * sqrt(12)."""
    p = pred.drop_nulls(["ret_exc_lead1m", "score"]).to_pandas()
    ic = p.groupby("eom").apply(lambda g: g["score"].corr(g["ret_exc_lead1m"], method="spearman")).dropna()
    sd = ic.std(ddof=1)
    return {"mean_ic": float(ic.mean()), "icir": float(ic.mean() / sd * np.sqrt(12)) if sd > 0 else float("nan"),
            "n_months": int(len(ic))}


# ===== src/report.py =====
"""
src/report.py - Steps 13-14: performance pack (performance.json + charts) and submission files (holdings.csv, returns.csv).
Chart style ported from the AlphaBERT repo (src/evaluate.py): 10x5 figures, default tab colours, curves anchored at 0 before
the first month, zero lines in black, hurdle as red dashed line, titles end with "gross of trading costs, <period>".
"""
import json
import numpy as np
import pandas as pd
import polars as pl
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt


def _rep_savefig(fig, path):
    path.parent.mkdir(parents=True, exist_ok=True)
    fig.tight_layout()
    fig.savefig(path, dpi=150)
    plt.close(fig)


def _rep_line(series, title, path, hline=None, ylabel=None):
    fig, ax = plt.subplots(figsize=(10, 5))
    for label, s in series.items():
        ax.plot(s.index, s.values, label=label)
    if hline is not None:
        ax.axhline(hline, color="black", lw=0.8)
    if ylabel:
        ax.set_ylabel(ylabel)
    ax.set_title(title)
    if len(series) > 1:
        ax.legend()
    _rep_savefig(fig, path)


def _rep_labels(keys, panel, filings) -> pl.DataFrame:
    """keys[permno, eom] -> + ticker, company_name from the panel row; gaps filled from the 8-K row nearest in filing_date."""
    k = keys.join(panel.select("permno", "eom", "ticker", "company_name"), on=["permno", "eom"], how="left").sort("eom")
    for col in ["ticker", "company_name"]:
        if filings is None or col not in filings.columns:
            continue
        fl = filings.select("permno", "filing_date", pl.col(col).alias(col + "_8k")).drop_nulls().sort("filing_date")
        if fl.height:
            k = (k.join_asof(fl, left_on="eom", right_on="filing_date", by="permno", strategy="nearest")
                 .with_columns(pl.col(col).fill_null(pl.col(col + "_8k"))).drop("filing_date", col + "_8k"))
    return k


def _rep_contrib(weights, panel, filings) -> pl.DataFrame:
    """Total gross contribution (sum of w*ret) of each stock, labelled "TICKER, Company Name", sorted descending."""
    c = (weights.join(panel.select("permno", "eom", "ret_exc_lead1m"), on=["permno", "eom"], how="left")
         .with_columns(c=pl.col("weight") * pl.col("ret_exc_lead1m").fill_null(0.0))
         .group_by("permno").agg(contrib=pl.col("c").sum(), eom=pl.col("eom").max()))
    c = _rep_labels(c, panel, filings).with_columns(
        label=pl.col("ticker").fill_null("?") + ", " + pl.col("company_name").fill_null("?").str.to_titlecase())
    return c.sort("contrib", descending=True).select("permno", "label", "contrib")


def _rep_composition(weights, panel) -> dict:
    """Largest weight, top-10 share of gross, short-book market cap / dollar volume / small-cap share (monthly means)."""
    w = weights.to_pandas().assign(a=lambda x: x["weight"].abs())
    top10 = w.groupby("eom")["a"].apply(lambda s: s.nlargest(10).sum() / s.sum())
    me = "me_raw" if "me_raw" in panel.columns else "market_equity"
    dv = "dolvol_raw" if "dolvol_raw" in panel.columns else "dolvol_126d"
    s = (weights.filter(pl.col("weight") < 0).join(
        panel.select("permno", "eom", me, dv, "size_grp"), on=["permno", "eom"], how="left").to_pandas())
    s["a"] = -s["weight"]
    s["small"] = s["size_grp"].isin(["micro", "nano", "small"]) * s["a"]
    g = s.groupby("eom")
    wavg = lambda col: float(g.apply(lambda x: np.average(x[col].fillna(0), weights=x["a"])).mean())
    return {"largest_weight": float(w["a"].max()), "top10_share_of_gross": float(top10.mean()),
            "short_avg_market_cap": wavg(me), "short_median_market_cap": float(s[me].median()),
            "short_avg_dollar_volume": wavg(dv), "short_median_dollar_volume": float(s[dv].median()),
            "short_small_cap_share": float((g["small"].sum() / g["a"].sum()).mean()),
            "small_cap_groups": ["micro", "nano", "small"]}


def performance_pack(rets, weights, panel, filings, preds, cfg) -> dict:
    """Write output/performance.json and the charts in output/figures/. Returns the stats dict."""
    out = cfg["output_dir"]
    figs = out / "figures"
    stats = summary_stats(rets, cfg)
    p = preds if "ret_exc_lead1m" in preds.columns else preds.join(
        panel.select("permno", "eom", "ret_exc_lead1m"), on=["permno", "eom"], how="left")
    stats["oos_r2"] = oos_r2(p)
    stats["book"] = _rep_composition(weights, panel)
    stats["n_missing_returns"] = int(weights.join(panel.select("permno", "eom", "ret_exc_lead1m"), on=["permno", "eom"],
                                                  how="left")["ret_exc_lead1m"].is_null().sum())
    stats["notes"] = ["S&P 500 series is the total return index from SP500.csv", "returns are gross of trading costs"]
    d = rets.to_pandas().set_index("Date")
    title = lambda t: f"{t}, gross of trading costs, {d.index[0]:%b %Y} to {d.index[-1]:%b %Y}"
    cum = lambda s: (1 + s).cumprod() - 1
    dd = lambda s: (1 + s).cumprod() / (1 + s).cumprod().cummax() - 1
    anchor = lambda s: pd.concat([pd.Series([0.0], index=[d.index[0] - pd.offsets.MonthBegin(1)]), s])
    _rep_line({"Strategy": anchor(cum(d["total"])), "Benchmark": anchor(cum(d["benchmark"])), "S&P 500": anchor(cum(d["sp500"]))},
              title("Cumulative return"), figs / "cumulative_returns.png", ylabel="Cumulative return")
    _rep_line({"Strategy": anchor(dd(d["total"])), "S&P 500": anchor(dd(d["sp500"]))},
              title("Drawdown"), figs / "underwater.png", ylabel="Drawdown")
    _rep_line({"Active return (ann.)": d["active"].rolling(12).mean() * 12},
              title("Rolling 12-month annualized active return"), figs / "rolling_active_return.png", hline=0)
    _rep_line({"IR": np.sqrt(12) * d["active"].rolling(12).mean() / d["active"].rolling(12).std(ddof=1)},
              title("Rolling 12-month information ratio"), figs / "rolling_ir.png", hline=0)
    x = d["sp500"] - d["rf"]
    _rep_line({"Beta": d["excess"].rolling(12).cov(x) / x.rolling(12).var()},
              title("Rolling 12-month beta vs S&P 500"), figs / "rolling_beta.png", hline=0)
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.hist(d["total"], bins=20, color="tab:blue", alpha=0.85)
    ax.axvline(d["benchmark"].mean(), color="red", linestyle="--", label="Avg monthly hurdle")
    ax.set_title(title("Distribution of monthly returns"))
    ax.legend()
    _rep_savefig(fig, figs / "return_histogram.png")
    c = _rep_contrib(weights, panel, filings).to_pandas()
    both = pd.concat([c.head(10), c.tail(10)])
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.barh(both["label"], both["contrib"], color=["tab:green" if v >= 0 else "tab:red" for v in both["contrib"]])
    ax.invert_yaxis()
    ax.set_title(title("Top/bottom return contributors (excess-return contribution)"))
    _rep_savefig(fig, figs / "contributors.png")
    stats["top_contributors"] = c.head(10).to_dict("records")
    stats["bottom_contributors"] = c.tail(10).to_dict("records")
    (out / "performance.json").write_text(json.dumps(stats, indent=2, default=float))
    return stats


def write_submission(weights, panel, filings, rets, cfg) -> dict:
    """output/holdings.csv (Date, PERMNO, TICKER, COMPANY NAME, WEIGHT in % of NAV) and output/returns.csv."""
    out = cfg["output_dir"]
    h = _rep_labels(weights.select("permno", "eom", "weight"), panel, filings)
    unl = h.filter(pl.col("ticker").is_null() | pl.col("company_name").is_null())["permno"].unique().to_list()
    h.sort("eom", "permno").select(
        Date=pl.col("eom").dt.offset_by("1mo").dt.month_start().dt.strftime("%Y-%m-%d"), PERMNO=pl.col("permno"),
        TICKER=pl.col("ticker").fill_null(""), **{"COMPANY NAME": pl.col("company_name").fill_null("")},
        WEIGHT=(pl.col("weight") * 100).round(6)).write_csv(out / "holdings.csv")
    rets.with_columns(Date=pl.col("Date").dt.strftime("%Y-%m-%d")).select(
        "Date", "total", "excess", "active", "long_leg", "short_leg", "benchmark", "sp500").write_csv(out / "returns.csv")
    if unl:
        print(f"WARNING: {len(unl)} stocks stay unlabeled after 8-K fill: {unl[:20]}")
    return {"unlabeled_permnos": unl}


# ===== src/agent.py =====
"""Explanation agent: LLM (tool calling) explains existing holdings; verifier keeps only quotes found in filings.
Explanations only - never feeds the signal or portfolio weights."""
import json
import re
import time
from datetime import date, datetime, timedelta
from pathlib import Path

import polars as pl


_AGENT_NOTE = ("explanations only; not used in portfolio construction; LLM pretraining may postdate the "
               "formation date, so explanations are post-hoc")
_AGENT_SYSTEM = (
    "You are a buy-side analyst. Explain why the systematic model is long/short this stock at this date using "
    "ONLY tool outputs (get_filings, get_profile, get_score). The company is anonymised; do not guess its identity. "
    " Every fact must carry a verbatim quote from a filing "
    "plus its document_id. Use no knowledge after the formation date. Reply with strict JSON: "
    '{"thesis": str, "facts": [{"fact": str, "quote": str, "document_id": str}], "risks": [str], "confidence": 0-1}.')
_AGENT_TOOLS = [
    {"type": "function", "function": {"name": n, "description": d, "parameters": {
        "type": "object", "properties": {"permno": {"type": "integer"}, p: {"type": "string", "description": "YYYY-MM-DD"}},
        "required": ["permno", p]}}}
    for n, d, p in [("get_filings", "Recent 8-K filings filed on/before before_eom", "before_eom"),
                    ("get_profile", "Known characteristics at month-end eom", "eom"),
                    ("get_score", "Model score and within-month percentile at eom", "eom")]]


def _agent_date(x):
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x
    return date.fromisoformat(str(x)[:10])


def _agent_cfg(cfg):
    return {"url": cfg.get("agent_url", "http://localhost:11434/v1/chat/completions"),
            "model": cfg.get("agent_model", "gpt-oss:20b"), "steps": int(cfg.get("agent_max_steps", 4)),
            "top_n": int(cfg.get("agent_top_n", 10)), "max_filings": int(cfg.get("agent_max_filings", 5)),
            "max_chars": int(cfg.get("agent_max_chars", 6000))}


def get_filings(cfg, permno, before_eom):
    """8-K filings for permno with filing_date <= before_eom (look-ahead control), latest first."""
    a = _agent_cfg(cfg)
    d = _agent_date(before_eom)
    df = (pl.scan_parquet(cfg["data_files"]["8k"]).filter(pl.col("permno") == int(permno))
          .select(["document_id", "permno", "filing_date", "items", "text"]
                  + [c for c in ("company_name", "ticker") if c in pl.read_parquet_schema(cfg["data_files"]["8k"])])
          .with_columns(pl.col("filing_date").cast(pl.Date))
          .filter(pl.col("filing_date") <= d).sort("filing_date", descending=True).head(a["max_filings"]).collect())
    # anonymise as in step 7 (firm names case-insensitive, tickers case-sensitive) so the LLM cannot recall what
    # happened to the firm later; names from the filings and from the panel for this permno
    names, ticks = set(), set()
    for path in (cfg["data_files"]["8k"], cfg["data_files"]["chars"]):
        sch = pl.read_parquet_schema(path)
        cols = [c for c in ("company_name", "ticker") if c in sch]
        if cols:
            pn = pl.scan_parquet(path).filter(pl.col("permno") == int(permno)).select(cols).unique().collect()
            names |= set(pn["company_name"].drop_nulls()) if "company_name" in cols else set()
            ticks |= set(pn["ticker"].drop_nulls()) if "ticker" in cols else set()
    return [{"document_id": str(r["document_id"]), "filing_date": str(r["filing_date"]), "items": str(r["items"]),
             "text": _txt_anonymise((r["text"] or "")[:a["max_chars"]], names, ticks)} for r in df.to_dicts()]


def get_profile(cfg, permno, eom):
    want = ["gics", "market_equity", "be_me", "ret_12_1", "beta_60m", "ret_exc"]   # no ticker/name: anonymised
    path = cfg["data_files"]["chars"]
    have = [c for c in want if c in pl.read_parquet_schema(path)]
    df = (pl.scan_parquet(path).filter(pl.col("permno") == int(permno))
          .select(["permno", "eom"] + have).with_columns(pl.col("eom").cast(pl.Date))
          .filter(pl.col("eom") == _agent_date(eom)).collect())
    if df.height == 0:
        return {}
    return {k: (str(v) if k in ("ticker", "company_name", "gics") else v) for k, v in df.select(have).to_dicts()[0].items()}


def get_score(cfg, permno, eom):
    p = Path(cfg["output_dir"]) / "predictions.parquet"
    if not p.exists():
        return {}
    df = (pl.scan_parquet(p).select(["permno", "eom", "score"]).with_columns(pl.col("eom").cast(pl.Date))
          .filter(pl.col("eom") == _agent_date(eom)).collect())
    if df.height == 0:
        return {}
    df = df.with_columns(((pl.col("score").rank() - 1) / max(df.height - 1, 1)).alias("pct"))
    r = df.filter(pl.col("permno") == int(permno))
    return {"score": r["score"][0], "percentile": r["pct"][0], "n_stocks": df.height} if r.height else {}


def _agent_dispatch(cfg, name, args, permno, formation_eom):
    """LLM args are untrusted: permno is forced to the held one, dates are capped at formation_eom."""
    cap = _agent_date(formation_eom)
    name = next((n for n in ("get_filings", "get_profile", "get_score") if str(name).startswith(n.rstrip("s"))), name)
    key = "before_eom" if name == "get_filings" else "eom"
    try:
        d = min(_agent_date(args.get(key)), cap)
    except Exception:
        d = cap
    if name == "get_filings":
        return get_filings(cfg, permno, d)
    if name == "get_profile":
        return get_profile(cfg, permno, d)
    if name == "get_score":
        return get_score(cfg, permno, d)
    return {"error": f"unknown tool {name}"}


def _agent_conn_err(e):
    import socket
    import urllib.error
    try:
        import requests
        if isinstance(e, (requests.exceptions.ConnectionError, requests.exceptions.Timeout)):
            return True
    except ImportError:
        pass
    return isinstance(e, (urllib.error.URLError, socket.timeout, ConnectionError))


def _agent_post(cfg, payload):
    url = _agent_cfg(cfg)["url"]
    try:
        import requests
    except ImportError:
        requests = None
    if requests is not None:
        r = requests.post(url, json=payload, timeout=(5, 120))
        r.raise_for_status()
        return r.json()
    import urllib.request
    req = urllib.request.Request(url, json.dumps(payload).encode(), {"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=120) as resp:
        return json.loads(resp.read().decode())


def _agent_parse(text):
    t = re.sub(r"^```(?:json)?\s*|\s*```$", "", (text or "").strip())
    try:
        return json.loads(t)
    except Exception:
        m = re.search(r"\{.*\}", t, re.S)
        if m:
            try:
                return json.loads(m.group(0))
            except Exception:
                pass
    return {"thesis": _agent_thesis(text), "facts": [], "risks": [], "confidence": 0.0}


def _agent_thesis(text):
    """Unparseable/truncated JSON: pull out the thesis string if present, else the raw text."""
    t = str(text or "")
    m = re.search(r'"thesis"\s*:\s*"((?:[^"\\]|\\.)*)', t, re.S)
    return (m.group(1).replace('\\"', '"') if m else t)[:800]


def _agent_norm(s):
    s = str(s or "").translate({0x2018: 39, 0x2019: 39, 0x201A: 39, 0x2032: 39, 0x201C: 34, 0x201D: 34, 0x201E: 34,
                                0x2010: 45, 0x2011: 45, 0x2012: 45, 0x2013: 45, 0x2014: 45, 0x2015: 45, 0x2212: 45,
                                0xA0: 32, 0x202F: 32, 0x2009: 32, 0x2026: 46})   # LLMs emit typographic variants
    return re.sub(r"\s+", " ", s).strip().lower()


def _agent_verify(facts, filings, formation_eom=None):
    """Keep a fact only if its quote occurs in the cited filing text (or any fetched filing if id missing).
    Only filings with filing_date <= formation_eom are eligible."""
    if formation_eom is not None:
        cap = _agent_date(formation_eom)
        filings = [f for f in filings if _agent_date(f["filing_date"]) <= cap]
    by_id = {str(f["document_id"]): _agent_norm(f["text"]) for f in filings}
    kept, dropped = [], []
    for f in facts if isinstance(facts, list) else []:
        q = _agent_norm(f.get("quote")) if isinstance(f, dict) else ""
        did = str(f.get("document_id", "") or "") if isinstance(f, dict) else ""
        pool = [by_id[did]] if did in by_id else (list(by_id.values()) if not did else [])
        (kept if q and any(q in t for t in pool) else dropped).append(f)
    return kept, dropped


def _agent_explain(cfg, permno, eom, side):
    a = _agent_cfg(cfg)
    ask = f"Stock permno={permno}, side={side.upper()}, formation month-end {eom}. Explain the position."
    msgs = [{"role": "system", "content": _AGENT_SYSTEM}, {"role": "user", "content": ask}]
    calls, filings, steps, content = [], [], 0, None
    try:
        for _ in range(a["steps"]):
            msg = _agent_post(cfg, {"model": a["model"], "messages": msgs, "tools": _AGENT_TOOLS})["choices"][0]["message"]
            steps += 1
            tcs = msg.get("tool_calls") or []
            if not tcs:
                content = msg.get("content")
                break
            msgs.append(msg)
            for tc in tcs:
                fn = tc["function"]
                args = fn["arguments"]
                args = json.loads(args) if isinstance(args, str) else args
                out = _agent_dispatch(cfg, fn["name"], args, permno, eom)
                if fn["name"] == "get_filings":
                    filings += out
                calls.append({"name": fn["name"], "args": args})
                msgs.append({"role": "tool", "tool_call_id": tc.get("id", ""), "content": json.dumps(out, default=str)})
        if content is None:  # step budget used up: force an answer
            msgs.append({"role": "user", "content": "Give the final JSON now."})
            content = _agent_post(cfg, {"model": a["model"], "messages": msgs})["choices"][0]["message"].get("content")
            steps += 1
    except Exception as e:
        if _agent_conn_err(e):
            raise
        # no tool-calling support: prefetch all tools, ask once
        print(f"[agent] tool mode failed ({type(e).__name__}); prefetch fallback")
        filings = get_filings(cfg, permno, eom)
        calls = [{"name": "get_filings", "args": {"permno": permno, "before_eom": eom}},
                 {"name": "get_profile", "args": {"permno": permno, "eom": eom}},
                 {"name": "get_score", "args": {"permno": permno, "eom": eom}}]
        ctx = {"get_filings": filings, "get_profile": get_profile(cfg, permno, eom), "get_score": get_score(cfg, permno, eom)}
        m2 = [{"role": "system", "content": _AGENT_SYSTEM},
              {"role": "user", "content": ask + "\nTool outputs:\n" + json.dumps(ctx, default=str)}]
        content = _agent_post(cfg, {"model": a["model"], "messages": m2})["choices"][0]["message"].get("content")
        steps = 1
    res = _agent_parse(content)
    kept, dropped = _agent_verify(res.get("facts"), filings, eom)
    return {"thesis": res.get("thesis", ""), "facts": kept, "dropped_facts": dropped, "risks": res.get("risks", []),
            "confidence": res.get("confidence", 0.0), "tool_calls": calls, "steps": steps}


def _agent_pick(hold_path, top_n):
    h = pl.read_csv(hold_path, try_parse_dates=True).with_columns(pl.col("Date").cast(pl.Date))
    h = h.with_columns(pl.col("WEIGHT" if "WEIGHT" in h.columns else "WEIGHT %").cast(pl.Float64).alias("w"))
    g = h.group_by("PERMNO").agg(pl.col("w").abs().mean().alias("avg_abs"), pl.col("w").mean().alias("avg_w"),
                                 pl.col("TICKER").first(), pl.col("COMPANY NAME").first())
    out = []
    for side, sub in (("long", g.filter(pl.col("avg_w") > 0)), ("short", g.filter(pl.col("avg_w") < 0))):
        for r in sub.sort("avg_abs", descending=True).head(top_n).to_dicts():
            peak = h.filter(pl.col("PERMNO") == r["PERMNO"]).sort(pl.col("w").abs(), descending=True)["Date"][0]
            out.append({"permno": int(r["PERMNO"]), "ticker": r["TICKER"], "name": r["COMPANY NAME"], "side": side,
                        "avg_weight": r["avg_w"], "formation_eom": str(peak.replace(day=1) - timedelta(days=1))})
    return out


def run_agent(cfg):
    a = _agent_cfg(cfg)
    out_dir, cache_dir = Path(cfg["output_dir"]), Path(cfg["cache_dir"])
    cache_p = cache_dir / "agent_cache.json"
    try:
        cache = json.loads(cache_p.read_text(encoding="utf-8"))
    except Exception:
        cache = {}
    rows = []
    for h in _agent_pick(out_dir / "holdings.csv", a["top_n"]):
        key = f"{h['permno']}|{h['formation_eom']}|{a['model']}"
        if key not in cache:
            try:
                cache[key] = _agent_explain(cfg, h["permno"], h["formation_eom"], h["side"])
            except Exception as e:
                if _agent_conn_err(e):
                    print(f"[agent] LLM endpoint unreachable ({type(e).__name__}); stopping agent run")
                    break
                print(f"[agent] {h['ticker']} failed: {e}")
                continue
        r = {**h, **cache[key]}
        if str(r.get("thesis", "")).lstrip().startswith("{"):
            r["thesis"] = _agent_thesis(r["thesis"])
        rows.append(r)
    cache_dir.mkdir(parents=True, exist_ok=True)
    cache_p.write_text(json.dumps(cache, default=str), encoding="utf-8")
    kept = sum(len(r["facts"]) for r in rows)
    drop = sum(len(r["dropped_facts"]) for r in rows)
    summ = {"n_holdings": len(rows), "verification_rate": kept / (kept + drop) if kept + drop else None,
            "verified_facts": kept, "dropped_facts": drop, "model": a["model"],
            "timestamp": datetime.now().isoformat(timespec="seconds"), "note": _AGENT_NOTE}
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / "agent_rationales.json").write_text(
        json.dumps({"summary": summ, "note": _AGENT_NOTE, "holdings": rows}, indent=2, default=str), encoding="utf-8")
    print(f"[agent] {len(rows)} holdings explained; verified {kept}/{kept + drop} facts; model {a['model']}")
    return rows


# ===== src/pipeline.py =====
"""
src/pipeline.py - Orchestration of steps 1-14: caching, step-10 tuning, step-11 leakage tests, step-12 ablations.
main(cfg) is called by MAIN.py; one short function per step.
"""
import itertools
import json
import time
from datetime import date, datetime
from pathlib import Path

import numpy as np
import polars as pl
import statsmodels.api as sm
from joblib import Parallel, delayed


_PIPE_T0 = time.time()
_PIPE_KEYS = ["permno", "eom"]
_PIPE_TONE = ["tone_mean", "tone_min", "tone_surprise"]


# ----------------------------------------------------------------------------- small helpers
def _pipe_log(msg):
    print(f"[{time.time() - _PIPE_T0:8.0f}s] {msg}", flush=True)


def _pipe_cached(path, fn):
    """Load parquet if present, else compute with fn() and write it."""
    path = Path(path)
    if path.exists():
        _pipe_log(f"cache hit {path.name}")
        return pl.read_parquet(path)
    out = fn()
    out.write_parquet(path)
    _pipe_log(f"cache written {path.name}")
    return out


def _pipe_cached_info(path, fn):
    """Like _pipe_cached, but fn() returns (frame, info) and info is kept in a sidecar JSON next to the parquet."""
    path = Path(path)
    side = path.with_suffix(".json")
    if path.exists():
        _pipe_log(f"cache hit {path.name}")
        return pl.read_parquet(path), (json.loads(side.read_text()) if side.exists() else None)
    out, info = fn()
    out.write_parquet(path)
    side.write_text(json.dumps(_pipe_clean(info), default=_pipe_jsonable))
    _pipe_log(f"cache written {path.name}")
    return out, info


def _pipe_path(cfg, name):
    """Cache path; smoke runs get their own files."""
    stem, ext = name.rsplit(".", 1)
    return Path(cfg["cache_dir"]) / f"{stem}{'_smoke' if cfg['smoke'] else ''}.{ext}"


def _pipe_jsonable(o):
    """json.dump default= hook: numpy / dates / paths / polars to plain Python."""
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, (np.floating,)):
        return None if np.isnan(o) else float(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    if isinstance(o, (date, datetime)):
        return o.isoformat()
    if isinstance(o, Path):
        return str(o)
    if isinstance(o, pl.DataFrame):
        return o.to_dicts()
    return str(o)


def _pipe_clean(o):
    """Recursively replace NaN floats by None (JSON has no NaN) and tuple keys by strings."""
    if isinstance(o, dict):
        return {str(k): _pipe_clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [_pipe_clean(v) for v in o]
    if isinstance(o, (float, np.floating)) and not np.isfinite(o):
        return None
    return o


def _pipe_dump(obj, name, cfg):
    path = Path(cfg["output_dir"]) / name
    path.write_text(json.dumps(_pipe_clean(obj), indent=2, default=_pipe_jsonable))
    _pipe_log(f"wrote {path.name}")


def _pipe_with_short(df, q, cfg):
    """Recompute short_eligible for a given short_me_q (mask may be an Expr or a Series)."""
    m = short_eligible_mask(df, q, cfg)
    return df.with_columns(m.alias("short_eligible"))


def _pipe_attach_target(preds, frame):
    """Add ret_exc_lead1m (needed by rank_ic / oos_r2) to a predictions frame."""
    return preds.drop("ret_exc_lead1m", strict=False).join(
        frame.select(_PIPE_KEYS + ["ret_exc_lead1m"]), on=_PIPE_KEYS, how="left")


def _pipe_scored(preds, frame, cfg, rm=None):
    """Predictions + optimizer inputs (short_eligible, betas, sector, size_z = within-month z of log market cap, risk_factors columns);
    with rm also spec_var (specific variance from the risk model; null -> month median, then global median)."""
    lm = pl.when(pl.col("me_raw") > 0).then(pl.col("me_raw").log())
    size_z = ((lm - lm.mean().over("eom")) / lm.std().over("eom")).fill_nan(None).fill_null(0.0).alias("size_z")
    cols = _PIPE_KEYS + ["short_eligible", "beta_kf", "beta_var", "sector", size_z] + [c for c in cfg["risk_factors"] if c not in ("sector",)]
    out = preds.select(_PIPE_KEYS + ["score"]).join(frame.select(cols), on=_PIPE_KEYS, how="left")
    if rm is not None:
        sv = pl.col("spec_var").fill_nan(None)
        out = out.join(rm["spec"].select(_PIPE_KEYS + ["spec_var"]), on=_PIPE_KEYS, how="left").with_columns(
            sv.fill_null(sv.median().over("eom")).fill_null(sv.median()))
    return out


def _pipe_ir(rets):
    a = rets["active"].to_numpy()
    sd = a.std(ddof=1) if len(a) > 1 else np.nan
    return float(np.sqrt(12) * a.mean() / sd) if sd and sd > 0 else float("nan")


def _pipe_beta(rets, cfg):
    """OLS of monthly excess return on S&P excess (sp500 - rf), Newey-West; returns {beta, t, alpha_m}."""
    rf = rets["benchmark"].to_numpy() - cfg["premium_annual"] / 12
    x = rets["sp500"].to_numpy() - rf
    y = rets["excess"].to_numpy()
    ok = np.isfinite(x) & np.isfinite(y)
    if ok.sum() < 5:
        return {"beta": float("nan"), "t": float("nan"), "alpha_m": float("nan")}
    r = sm.OLS(y[ok], sm.add_constant(x[ok])).fit(cov_type="HAC", cov_kwds={"maxlags": cfg["nw_lags"]})
    return {"beta": float(r.params[1]), "t": float(r.tvalues[1]), "alpha_m": float(r.params[0])}


def _pipe_stats(rets, cfg):
    """IR, S&P beta and annualised Sharpe of the excess return of a book_returns frame."""
    x = rets["excess"].to_numpy()
    sd = x.std(ddof=1) if len(x) > 1 else np.nan
    return {"ir": _pipe_ir(rets), "beta": _pipe_beta(rets, cfg)["beta"],
            "sharpe": float(np.sqrt(12) * x.mean() / sd) if sd and sd > 0 else float("nan")}


def _pipe_ic_map(infos, frame, cfg, val=False):
    """Pre-test IC for the v2 book: val=True -> the 2021 window's validation IC (float, for validation books);
    else dict test eom -> that window's validation IC (windows without one get the mean of the others)."""
    if val:
        return float(infos[0].get("val_ic") or 0.0)
    ics = {i["year"]: i.get("val_ic") for i in infos}
    fb = float(np.mean([v for v in ics.values() if v is not None] or [0.0]))
    tm = frame.select("eom", "target_month").unique()
    return {e: float(ics[t.year] if ics[t.year] is not None else fb) for e, t in tm.iter_rows() if t.year in ics}


def _pipe_ic(preds, frame, cfg):
    """Mean rank IC, ICIR (mean/std*sqrt12) and month count of a predictions frame."""
    ic = rank_ic(_pipe_attach_target(preds, frame), cfg)["ic"].drop_nulls().to_numpy()
    sd = ic.std(ddof=1) if len(ic) > 1 else np.nan
    return {"ic": float(ic.mean()) if len(ic) else float("nan"),
            "icir": float(ic.mean() / sd * np.sqrt(12)) if len(ic) > 1 and sd > 0 else float("nan"),
            "n_months": int(len(ic))}


# ----------------------------------------------------------------------------- steps 1-8 (data, features)
def _pipe_data(cfg):
    """Steps 1-3: raw panel, 147 factors, filings, preprocessed universe (cached) and missing-flag columns."""
    panel, factors, filings = load_inputs(cfg)
    _pipe_log(f"loaded panel {panel.shape}, filings {filings.shape}")

    def build():
        return preprocess(build_universe(panel, cfg), factors, cfg)[0]
    df = _pipe_cached(_pipe_path(cfg, "universe.parquet"), build)
    flag_cols = [c for c in df.columns if c.endswith("_miss")]
    return panel, factors, filings, df, flag_cols


def _pipe_kalman(panel, df, cfg, logs):
    """Step 8 on the RAW panel (all stocks), joined onto the universe."""
    def build():
        return kalman_betas(panel, cfg)
    kal, logs["kalman"] = _pipe_cached_info(_pipe_path(cfg, "kalman.parquet"), build)
    return df.drop(["beta_kf", "beta_var"], strict=False).join(kal, on=_PIPE_KEYS, how="left")


def _pipe_text(filings, panel, df, cfg):
    """Steps 6-7: event flags + FinBERT tone features; returns (frame with text cols, event cols)."""
    keys = df.select(_PIPE_KEYS)

    def build():
        ev = event_flags(filings, keys, cfg)
        tones = finbert_doc_tones(filings, df, cfg)
        return ev.join(tone_features(filings, tones, keys, cfg), on=_PIPE_KEYS, how="left")
    txt = _pipe_cached(_pipe_path(cfg, "text_features.parquet"), build)
    event_cols = [c for c in txt.columns if c not in _PIPE_KEYS + _PIPE_TONE]
    return df.join(txt, on=_PIPE_KEYS, how="left"), event_cols


def _pipe_gru(df, factors, cfg, logs):
    """Step 4 for each d in the grid; returns {d: embedding frame}."""
    embs = {}
    for d in cfg["gru_d_grid"]:
        def build(d=d):
            return gru_embeddings(df, factors, d, cfg)
        embs[d], info = _pipe_cached_info(_pipe_path(cfg, f"gru_d{d}.parquet"), build)
        logs.setdefault("gru", {})[d] = info
    return embs


def _pipe_frame(df, emb, q, cfg):
    """Full modelling frame for one GRU d and short_me_q."""
    return _pipe_with_short(df.join(emb, on=_PIPE_KEYS, how="left"), q, cfg)


# ----------------------------------------------------------------------------- step 10 tuning
def _pipe_book_job(scored, ltc, lb, lr, lf, rm, cfg):
    """Worker: one optimizer run over all months of `scored`."""
    return run_book(scored, ltc, lb, cfg, lam_risk=lr, lam_fac=lf, rm=rm)


def _pipe_tune(frames, feats, market, cfg, rm, vals=None):
    """Step 10: XGB on the 2021 window per d (skipped if `vals` given), then grid over
    (lam_tc, lam_beta, short_me_q, lam_risk, lam_fac) by validation IR. Validation months only. -> (choice, grid, rets, vals)"""
    win = windows(cfg)[0]
    fit, vals, tasks = vals is None, dict(vals or {}), []
    for d in cfg["gru_d_grid"]:
        fr = frames[d].filter(pl.col("target_month") <= win["test"][1])
        if fit:
            _, vals[d], info = fit_predict_year(fr, feats[d], win, cfg)
            _pipe_log(f"tune: d={d} xgb val IC {info.get('val_ic')}")
        for q in cfg["short_me_q_grid"]:
            sc = _pipe_scored(vals[d], _pipe_with_short(fr, q, cfg), cfg)
            tasks += [(d, ltc, lb, q, lr, lf, sc) for ltc in cfg["lambda_tc_grid"] for lb in cfg["lambda_beta_grid"]
                      for lr in cfg["lambda_risk_grid"] for lf in cfg["lambda_fac_grid"]]
    _pipe_log(f"tune: {len(tasks)} optimizer runs on {cfg['n_jobs']} workers")
    res = Parallel(n_jobs=cfg["n_jobs"], backend="loky")(
        delayed(_pipe_book_job)(sc, ltc, lb, lr, lf, rm, cfg) for d, ltc, lb, q, lr, lf, sc in tasks)
    grid, best = [], None
    for (d, ltc, lb, q, lr, lf, _), (w, log) in zip(tasks, res):
        rets, _ = book_returns(w, frames[d], market, cfg)
        ir = _pipe_ir(rets)
        grid.append({"d": d, "lam_tc": ltc, "lam_beta": lb, "short_me_q": q, "lam_risk": lr, "lam_fac": lf, "val_ir": ir,
                     "n_relaxed_months": sum(1 for r in log if (r.get("beta_tol") or 0) > cfg["beta_tol"] + 1e-12)})
        if np.isfinite(ir) and (best is None or ir > best[0]):
            best = (ir, grid[-1], rets)
    choice = {k: best[1][k] for k in ["d", "lam_tc", "lam_beta", "short_me_q", "lam_risk", "lam_fac"]} | {"val_ir": best[0]}
    return choice, grid, best[2], vals


def _pipe_beta_check(rets, cfg):
    """Chosen validation book vs S&P: beta is clearly nonzero (warning) when |t| > beta_check_t."""
    b = _pipe_beta(rets, cfg)
    b["warning"] = bool(abs(b["t"]) > cfg["beta_check_t"])
    if b["warning"]:
        print(f"WARNING: validation book beta to S&P = {b['beta']:.3f} (t={b['t']:.2f}) is clearly nonzero", flush=True)
    return b


def _pipe_beta_factor(df, cfg, rm):
    """Factor-model beta per stock-month: exposures(eom rows) @ rm["b"][eom] (b uses returns realised by eom); kf where b missing."""
    out = []
    for (e,), g in df.group_by("eom", maintain_order=True):
        b = (rm.get("b") or {}).get(e)
        bk = g["beta_kf"].to_numpy().astype(float)
        if b is not None:
            bk = risk_exposures(g, rm["sectors"], cfg) @ np.asarray(b, float)
        out.append(pl.DataFrame({"permno": g["permno"], "eom": g["eom"], "beta_kf": bk, "beta_var": g["beta_var"]}))
    return df.select(_PIPE_KEYS).join(pl.concat(out), on=_PIPE_KEYS, how="left")


def _pipe_beta_variant(name, df, panel, cfg, logs, rm=None):
    """Beta estimates [permno, eom, beta_kf, beta_var] for one variant (kf_rfloor is cached)."""
    kf = df.select(_PIPE_KEYS + ["beta_kf", "beta_var"])
    if name == "kf":
        return kf
    if name == "factor":
        return _pipe_beta_factor(df, cfg, rm)
    if name == "kf_rfloor":
        def build():
            return kalman_betas(panel, cfg, r_floor=cfg["kalman_r_floor"])
        out, logs["kalman_rfloor"] = _pipe_cached_info(_pipe_path(cfg, "kalman_rfloor.parquet"), build)
        return df.select(_PIPE_KEYS).join(out, on=_PIPE_KEYS, how="left")
    k, b = cfg["beta_shrink"], pl.col("beta_60m")          # b60_shrunk; raw beta_60m clipped at its 1st/99th pct (raw reaches +/-1e4)
    fit = panel.filter(pl.col("eom") <= date.fromisoformat(cfg["kalman_fit_end_eom"]))["beta_60m"]   # pre-2019 only
    lo, hi = fit.quantile(0.01), fit.quantile(0.99)
    raw = panel.select(_PIPE_KEYS + [b.clip(lo, hi).alias("beta_60m")])
    return kf.join(raw, on=_PIPE_KEYS, how="left").with_columns(
        beta_kf=pl.when(b.is_not_null()).then((1 - k) * b + k).otherwise(pl.col("beta_kf"))).drop("beta_60m")


def _pipe_swap_beta(frames, bv):
    return {d: fr.drop(["beta_kf", "beta_var"]).join(bv, on=_PIPE_KEYS, how="left") for d, fr in frames.items()}


def _pipe_beta_fix(df, panel, frames, feats, vals, choice, chk, market, cfg, rm, logs):
    """Step 10 beta fix: validation beta of each variant at the current choice; if the best is not "kf", redo the grid.
    -> (frames, choice, grid, check, log); grid is None when "kf" is kept."""
    fix, swapped = {"variants": {}, "choice_kf": choice, "check_kf": chk}, {}
    for name in cfg["beta_variants"]:
        swapped[name] = _pipe_swap_beta(frames, _pipe_beta_variant(name, df, panel, cfg, logs, rm))
        fr = _pipe_with_short(swapped[name][choice["d"]], choice["short_me_q"], cfg)
        v = fix["variants"][name] = _pipe_beta(_pipe_run_book_stats(vals[choice["d"]], fr, choice, market, cfg, rm, spec=True)[1], cfg)
        _pipe_log(f"beta fix: {name} val beta {v['beta']:.3f} (t={v['t']:.2f})")
    best = min(fix["variants"], key=lambda n: abs(fix["variants"][n]["beta"]) if np.isfinite(fix["variants"][n]["beta"]) else np.inf)
    fix["chosen"], grid = best, None
    if best != "kf":
        frames = swapped[best]
        choice, grid, rets, _ = _pipe_tune(frames, feats, market, cfg, rm, vals)
        chk = _pipe_beta_check(rets, cfg)
        fix |= {"choice_final": choice, "check_final": chk}
    _pipe_log(f"beta fix: variant {best}; val beta {chk['beta']:.3f} (t={chk['t']:.2f}); choice {choice}")
    return frames, choice, grid, chk, fix


# ----------------------------------------------------------------------------- book v4 (port of teammate optimizer)
def _pipe_v4_scored(preds, frame, panel, cfg, rm=None):
    """Scored frame for run_book_v4: score, short_eligible, size_grp and the RAW beta_60m (joined from the raw panel)."""
    sc = _pipe_scored(preds, frame, cfg, rm)
    if "size_grp" in frame.columns:
        sc = sc.join(frame.select(_PIPE_KEYS + ["size_grp"]), on=_PIPE_KEYS, how="left")
        extra = []
    else:
        extra = ["size_grp"]
    return sc.join(panel.select(_PIPE_KEYS + extra + [pl.col("beta_60m").alias("beta_60m_raw")]), on=_PIPE_KEYS, how="left")


def _pipe_v4_configs(cfg):
    g = cfg["v4_grid"]
    return [dict(zip(g, v)) for v in itertools.product(*g.values())]


def _pipe_v4_net(rets, cfg):
    """book_returns frame with the v4 fee charged: total / active / excess minus v4_fee * turnover."""
    fee = cfg["v4_fee"] * pl.col("turnover")
    return rets.with_columns(total=pl.col("total") - fee, active=pl.col("active") - fee, excess=pl.col("excess") - fee)


def _pipe_v4_job(sc, params, frame, market, v4rets, cfg):
    w, log = run_book_v4(sc, cfg, {e: params for e in sc["eom"].unique().to_list()}, v4rets)
    if w.height == 0 or any(str(r.get("attempt", "")).startswith("hold") for r in log):   # incomplete: disqualify (as teammate)
        return float("nan"), float("nan"), float("nan")
    rets, _ = book_returns(w, frame, market, cfg)
    return _pipe_ir(_pipe_v4_net(rets, cfg)), _pipe_ir(rets), float(rets["turnover"].mean())


def _pipe_v4_tune(vals_by_year, frame, panel, market, cfg, v4rets):
    """Per test year Y: grid of v4 params on that window's 24 validation months (its train-only val_pred), best IR net of v4_fee.
    -> (params {year: dict}, log {year: [grid rows]})"""
    cfgs, params, log = _pipe_v4_configs(cfg), {}, {}
    for y, vp in sorted(vals_by_year.items()):
        sc = _pipe_v4_scored(vp, frame, panel, cfg)
        lo = sc["eom"].min()
        fr = frame.select("permno", "eom", "ret_exc_lead1m").filter(pl.col("eom") >= lo)        # only what book_returns needs
        vr = v4rets.filter(pl.col("eom") > pl.lit(lo).dt.offset_by("-40mo"))                   # covers the max cov window
        res = Parallel(n_jobs=cfg["n_jobs"], backend="loky")(delayed(_pipe_v4_job)(sc, p, fr, market, vr, cfg) for p in cfgs)
        log[y] = [{**p, "net_ir": r[0], "gross_ir": r[1], "turnover": r[2]} for p, r in zip(cfgs, res)]
        ok = [(r[0], i) for i, r in enumerate(res) if np.isfinite(r[0])]
        # all configs disqualified (incomplete books): keep last year's choice, else the most risk-averse full-gross config
        fallback = params[max(params)] if params else max(cfgs, key=lambda p: (p["gross"], p["risk_penalty"], p["turnover_penalty"]))
        params[y] = cfgs[max(ok)[1]] if ok else fallback
        _pipe_log(f"v4 tuning {y}: {params[y]} net IR {max(ok)[0] if ok else float('nan'):.3f}")
    return params, log


def _pipe_v4_book(preds, frame, cfg, rm, v4, val=False):
    """v4 book on `preds`: val=True -> constant first-window (2021) params (pre-test); else each eom uses its test year's chosen
    params (year = target_month.year), w_prev carried across years. -> (weights, log)"""
    sc = _pipe_v4_scored(preds, frame, v4["panel"], cfg, rm)
    if val:
        pm = {e: v4["params"][min(v4["params"])] for e in sc["eom"].unique().to_list()}
    else:
        tm = frame.select("eom", "target_month").unique()
        last = v4["params"][max(v4["params"])]
        pm = {e: v4["params"].get(t.year, last) for e, t in tm.iter_rows() if t is not None}
    return run_book_v4(sc, cfg, pm, v4["rets"])


# ----------------------------------------------------------------------------- full run + step 11 / 12 helpers
def _pipe_book(preds, frame, choice, cfg, rm, ic, spec=False, v4=None):
    """Main book cfg["book"]: "spec" (chosen lambdas), "v2" (alpha = ic * xs_vol * z) or "v3_s<smooth>" (sector-neutral tail book);
    spec=True forces the spec book. Logs the number of months with relaxed constraints. -> (weights, log)"""
    book = "spec" if spec else cfg["book"]
    if book == "v4":
        w, log = _pipe_v4_book(preds, frame, cfg, rm, v4, val=bool(v4.get("val")))
        _pipe_log(f"book v4: {len(log)} months")
        return w, log
    sc = _pipe_scored(preds, frame, cfg, rm)
    if book == "v2":
        w, log = run_book_v2(sc, cfg, rm, ic)
    elif book.startswith("v3_s"):
        w, log = run_book_v3(sc, cfg, float(book[4:]))
    else:
        book = "spec"
        w, log = run_book(sc, choice["lam_tc"], choice["lam_beta"], cfg, lam_risk=choice["lam_risk"], lam_fac=choice["lam_fac"], rm=rm)
    n_rel = sum(1 for r in log if isinstance(r, dict) and any(v for k, v in r.items() if "relax" in k))
    _pipe_log(f"book {book}: {len(log)} months, {n_rel} with relaxed constraints")
    return w, log


def _pipe_run_book_stats(preds, frame, choice, market, cfg, rm, ic=None, spec=False, v4=None):
    """Main book (see _pipe_book) on `preds` -> (weights, rets, n_missing_returns)."""
    w, _ = _pipe_book(preds, frame, choice, cfg, rm, ic, spec, v4)
    rets, n_miss = book_returns(w, frame, market, cfg)
    return w, rets, n_miss


def _pipe_candidates(cfg):
    return ["spec", "v2"] + [f"v3_s{x}" for x in cfg["v3_smooth_grid"]] + ["v4"]


def _pipe_select_book(val_2021, preds, frame, choice, market, cfg, rm, infos, v4=None):
    """cfg["book"] == "auto": pick the candidate with the highest 2019-2020 validation IR (test stats are computed afterwards, for the
    record only). Explicit cfg["book"] is kept. -> (cfg with the chosen book, book_selection dict)"""
    ic_val, ic_test = _pipe_ic_map(infos, frame, cfg, val=True), _pipe_ic_map(infos, frame, cfg)
    cands = _pipe_candidates(cfg) if cfg["book"] == "auto" else [cfg["book"]]
    val = {c: _pipe_stats(_pipe_run_book_stats(val_2021, frame, choice, market, {**cfg, "book": c}, rm, ic_val, v4=v4 and {**v4, "val": True})[1], cfg) for c in cands}
    # market-neutral mandate: only books with |validation beta| <= 0.2 are eligible; else the smallest |beta|
    ok = [c for c in cands if np.isfinite(val[c]["beta"]) and abs(val[c]["beta"]) <= 0.2]
    best = (max(ok, key=lambda c: val[c]["ir"] if np.isfinite(val[c]["ir"]) else -np.inf) if ok
            else min(cands, key=lambda c: abs(val[c]["beta"]) if np.isfinite(val[c]["beta"]) else np.inf))
    cfg = {**cfg, "book": best}
    test = {c: _pipe_stats(_pipe_run_book_stats(preds, frame, choice, market, {**cfg, "book": c}, rm, ic_test, v4=v4)[1], cfg) for c in cands}
    _pipe_log("book selection (val IR/beta): " + ", ".join(f"{c} {val[c]['ir']:.3f}/{val[c]['beta']:.3f}" for c in cands) + f" -> {best}")
    return cfg, {"rule": "highest 2019-2020 validation IR among books with |validation beta| <= 0.2", "chosen": best, "validation": val, "test_for_transparency": test}


def _pipe_leak_filings(filings, feats):
    """Number of stock-months flagged has_filing=1 without a filing in that calendar month, and filings used after their eom."""
    f = filings.select("permno", pl.col("filing_date").dt.month_end().alias("eom"), "filing_date")
    have = f.group_by(_PIPE_KEYS).agg(pl.col("filing_date").max().alias("last"))
    x = feats.filter(pl.col("has_filing") == 1).select(_PIPE_KEYS).join(have, on=_PIPE_KEYS, how="left")
    return {"flagged_without_filing": int(x["last"].is_null().sum()),
            "filing_after_eom": int((x["last"] > x["eom"]).sum())}


def _pipe_leak_windows(wins):
    """Violations of train < val < test ordering by target month, and of 'train ends before test year'."""
    bad = 0
    for w in wins:
        bad += not (w["train"][1] < w["val"][0] <= w["val"][1] < w["test"][0])
        bad += w["train"][1].year >= w["year"] or w["val"][1].year >= w["year"]
        bad += w["test"][0].year != w["year"]
    return int(bad)


def _pipe_leak_target(df, features, target="ret_exc_lead1m"):
    """Feature columns that are the target (by name) or numerically identical / perfectly correlated with it."""
    bad = [c for c in features if c == target or "lead" in c]
    num = [c for c in features if c not in bad and df.schema[c].is_numeric()]
    if num:
        cors = df.select([pl.corr(pl.col(c).cast(pl.Float64), pl.col(target)).alias(c) for c in num]).row(0)
        bad += [c for c, r in zip(num, cors) if r is not None and abs(r) > 0.999]
    return bad


def _pipe_leak_target_months(infos):
    """Windows whose fitted train/val rows reach a target month >= Y-01-01 (taken from the actual fits)."""
    return [{"year": i["year"], "max_target_month": i["train_max_target"]}
            for i in infos if i["train_max_target"] >= date(i["year"], 1, 1)]


def _pipe_leak_dups(df):
    return int(df.height - df.unique(subset=_PIPE_KEYS).height)


def _pipe_leakage(frame, filings, feats, event_cols, preds_shuf, choice, market, cfg, rm, infos, shuf_infos=None, v4=None):
    """Step 11: structural checks plus shuffled-label run (test IC and IR should be ~0)."""
    ev = frame.filter(pl.col("has_filing") == 1) if "has_filing" in frame.columns else frame.head(0)
    out = {"filings": _pipe_leak_filings(filings, ev) if ev.height else {"flagged_without_filing": 0, "filing_after_eom": 0},
           "window_violations": _pipe_leak_windows(windows(cfg)),
           "target_like_features": _pipe_leak_target(frame, feats),
           "duplicate_permno_eom": _pipe_leak_dups(frame),
           "train_target_month_violations": _pipe_leak_target_months(infos),
           "shuffled_ic": _pipe_ic(preds_shuf, frame, cfg)}
    _, rets, _ = _pipe_run_book_stats(preds_shuf, frame, choice, market, cfg, rm, _pipe_ic_map(shuf_infos or infos, frame, cfg), v4=v4)
    out["shuffled_ir"] = _pipe_ir(rets)
    out["shuffled_beta"] = _pipe_beta(rets, cfg)
    out["passed_structural"] = (out["filings"]["flagged_without_filing"] == 0 and out["filings"]["filing_after_eom"] == 0
                                and out["window_violations"] == 0 and not out["target_like_features"]
                                and out["duplicate_permno_eom"] == 0 and not out["train_target_month_violations"])
    out["ic_close_to_zero"] = bool(abs(out["shuffled_ic"]["ic"]) < 0.01)
    out["ir_close_to_zero"] = bool(abs(out["shuffled_ir"]) < 1.0)
    if not (out["ic_close_to_zero"] and out["ir_close_to_zero"]):
        print(f"WARNING: shuffled-label run not ~0: IC {out['shuffled_ic']['ic']:.4f}, IR {out['shuffled_ir']:.2f}", flush=True)
    return out


def _pipe_ablations(frame, runs, choice, market, cfg, rm, v4=None):
    """Step 12: per ablation - validation/test rank IC, ICIR, IR, beta (chosen lambdas); IC on has_filing=1 rows for 4, 5 and 6. Main book, each ablation's own val ICs."""
    jobs = [(r["preds"], _pipe_ic_map(r["infos"], frame, cfg), v4) if k == "preds" else (r["val"], _pipe_ic_map(r["infos"], frame, cfg, val=True), v4 and {**v4, "val": True})
            for r in runs.values() for k in ("preds", "val")]
    books = Parallel(n_jobs=min(cfg["n_jobs"], len(jobs)), backend="loky")(
        delayed(_pipe_run_book_stats)(p, frame, choice, market, cfg, rm, ic, False, v4_) for p, ic, v4_ in jobs)
    out = {"features_note": "ablation 1 = 147 factors (ridge), 2 = the 147 factors only (XGB); missing-value flags enter from "
                            "ablation 3 onward; 5 = full feature set without CFI; 6 = same plus CFI feature selection (the main run, reused). val_ir/val_beta: book on 2021-window val_pred."}
    for i, (name, r) in enumerate(runs.items()):
        _, rets, n_miss = books[2 * i]
        vrets = books[2 * i + 1][1]
        o = {"features": r["n_features"], "val_ir": _pipe_ir(vrets), "val_beta": _pipe_beta(vrets, cfg)["beta"], "test": _pipe_ic(r["preds"], frame, cfg), "val_2021": _pipe_ic(r["val"], frame, cfg),
             "val_ic_by_year": [i.get("val_ic") for i in r["infos"]],
             "ir": _pipe_ir(rets), "beta": _pipe_beta(rets, cfg), "n_missing_returns": n_miss}
        if r.get("has_filing_ic"):
            hf = frame.filter(pl.col("has_filing") == 1).select(_PIPE_KEYS)
            o["test_has_filing_rows"] = _pipe_ic(r["preds"].join(hf, on=_PIPE_KEYS, how="inner"), frame, cfg)
        out[name] = o
    return out


# ----------------------------------------------------------------------------- main
def main(cfg):
    """Run steps 1-14 end to end."""
    logs, out_dir = {}, Path(cfg["output_dir"])
    panel, factors, filings, df, flag_cols = _pipe_data(cfg)
    df = _pipe_kalman(panel, df, cfg, logs)
    df, event_cols = _pipe_text(filings, panel, df, cfg)
    embs = _pipe_gru(df, factors, cfg, logs)
    market = load_market(cfg)

    base = factors + flag_cols
    gru_cols = lambda d: [f"gru_{i}" for i in range(1, d + 1)]
    feats = {d: base + gru_cols(d) + event_cols + _PIPE_TONE for d in cfg["gru_d_grid"]}
    frames = {d: _pipe_frame(df, embs[d], cfg["short_me_q"], cfg) for d in cfg["gru_d_grid"]}
    t0 = time.time()
    rm = risk_model(frames[cfg["gru_d_grid"][0]], cfg, market)     # once per run: independent of d, betas, short_me_q
    _pipe_log(f"risk model: {len(rm['L'])} months with a covariance, {time.time() - t0:.1f}s")

    # step 10a: non-CFI validation fit, used ONLY to choose d (GRU size); the portfolio parameters are re-chosen in 10b on the CFI scores
    choice_10a, _, _, _ = _pipe_tune(frames, feats, market, cfg, rm)
    _pipe_log(f"step 10a choice (d only) {choice_10a}")
    d = choice_10a["d"]
    full = feats[d]

    # step 5 + 9: full schedule (CFI) on the 10a frame; beta variants only change optimizer inputs, not XGB features
    cfi = {"cfi_factors": factors} if cfg.get("cfi_enabled") else {}
    preds, val_2021, infos, vals_y = run_schedule(_pipe_with_short(frames[d], choice_10a["short_me_q"], cfg), full, cfg, return_vals=True, **cfi)
    cfi_log = {}
    for i in infos:
        c = i.get("cfi")
        if c:
            cfi_log[i["year"]] = c
            _pipe_log(f"cfi {i['year']}: {c['chosen']} n_factors={c['n_factors']} val IC {c['val_ic_base']:.4f} -> {c['val_ic_chosen']:.4f}")

    # step 10b: portfolio grid for the chosen d on the CFI validation scores (the signal the book is traded on), then beta check / fix
    cfg_d = {**cfg, "gru_d_grid": [d]}
    choice, grid, val_rets, _ = _pipe_tune(frames, feats, market, cfg_d, rm, {d: val_2021})
    beta_chk, beta_fix = _pipe_beta_check(val_rets, cfg), None
    if beta_chk["warning"]:
        frames, choice, grid2, beta_chk, beta_fix = _pipe_beta_fix(df, panel, frames, feats, {d: val_2021}, choice, beta_chk, market, cfg_d, rm, logs)
        if grid2:
            beta_fix["grid_kf"], grid = grid, grid2
    _pipe_log(f"step 10b choice {choice}; validation beta {beta_chk}")
    frame = _pipe_with_short(frames[d], choice["short_me_q"], cfg)
    _pipe_dump({"choice_10a": choice_10a, "choice": choice, "beta_check": beta_chk, "beta_fix": beta_fix, "grid": grid, "logs": logs}, "settings_log.json", cfg)
    preds = preds.select(_PIPE_KEYS + ["score", "ret_hat"])
    preds.write_parquet(out_dir / "predictions.parquet")
    ic_test = _pipe_ic_map(infos, frame, cfg)           # per test year: that window's validation IC (a pre-test quantity)
    # book v4: params per test year tuned on that window's validation months only (net of v4_fee)
    v4rets = panel.select("permno", "eom", "ret")
    v4_params, v4_log = _pipe_v4_tune(vals_y, frame, panel, market, cfg, v4rets)
    v4 = {"params": v4_params, "rets": v4rets, "panel": panel.select([c for c in ("permno", "eom", "beta_60m", "size_grp") if c in panel.columns])}
    _pipe_dump({"v4_tuning": v4_log, "v4_chosen": v4_params}, "settings_log.json", cfg)
    cfg, book_sel = _pipe_select_book(val_2021, preds, frame, choice, market, cfg, rm, infos, v4)
    weights, rets, n_miss = _pipe_run_book_stats(preds, frame, choice, market, cfg, rm, ic_test, v4=v4)
    net_stats = {"fee": cfg["v4_fee"], "ir_net_of_fee": _pipe_ir(_pipe_v4_net(rets, cfg)), "ir_gross": _pipe_ir(rets),
                 "mean_turnover": float(rets["turnover"].mean())}
    _pipe_log(f"full book ({cfg['book']}): IR {_pipe_ir(rets):.3f}, missing returns {n_miss}")
    # comparison: spec book on the same test predictions; main book on 2019-2020 validation (a check, nothing tuned on it)
    test_stats = _pipe_stats(rets, cfg)
    spec_book = _pipe_stats(_pipe_run_book_stats(preds, frame, choice, market, cfg, rm, spec=True, v4=v4)[1], cfg)
    v2_val = _pipe_stats(_pipe_run_book_stats(val_2021, frame, choice, market, cfg, rm, _pipe_ic_map(infos, frame, cfg, val=True), v4=v4 and {**v4, "val": True})[1], cfg)
    _pipe_log(f"{cfg['book']} test IR {test_stats['ir']:.3f} beta {test_stats['beta']:.3f} | spec test IR {spec_book['ir']:.3f} "
              f"beta {spec_book['beta']:.3f} | {cfg['book']} val IR {v2_val['ir']:.3f} beta {v2_val['beta']:.3f}")
    performance_pack(rets, weights, frame, filings, _pipe_attach_target(preds, frame), cfg)
    write_submission(weights, frame, filings, rets, cfg)
    _pipe_dump({"choice_10a": choice_10a, "choice": choice, "beta_check": beta_chk, "beta_fix": beta_fix, "grid": grid, "logs": logs, "xgb_infos": infos, "cfi": cfi_log,
                "test_ic": _pipe_ic(preds, frame, cfg), "test_ir": _pipe_ir(rets), "test_beta": _pipe_beta(rets, cfg),
                "book": cfg["book"], "test_stats": test_stats, "spec_book": spec_book, "v2_validation": v2_val, "book_selection": book_sel,
                "v4_tuning": v4_log, "v4_chosen": v4_params, "chosen_book_net_of_fee": net_stats},
               "settings_log.json", cfg)

    # step 12: ablations (each run reuses the chosen lambdas / short_me_q / d)
    sets = {"1_ridge_147": (factors, "ridge", False),
            "2_xgb_base": (factors, "xgb", False),
            "3_plus_gru": (base + gru_cols(d), "xgb", False),
            "4_plus_event": (base + gru_cols(d) + event_cols, "xgb", True)}
    runs = {}
    for name, (cols, model, hf) in sets.items():
        p, v, i = run_schedule(frame, cols, cfg, model=model)
        runs[name] = {"preds": p, "val": v, "infos": i, "n_features": len(cols), "has_filing_ic": hf}
        _pipe_log(f"ablation {name} done")
    p, v, i = run_schedule(frame, full, cfg)         # full feature set, no CFI: isolates CFI in ablation 6
    runs["5_plus_tone"] = {"preds": p, "val": v, "infos": i, "n_features": len(full), "has_filing_ic": True}
    _pipe_log("ablation 5_plus_tone done")
    runs["6_plus_cfi"] = {"preds": preds, "val": val_2021, "infos": infos, "n_features": len(full), "has_filing_ic": True}
    _pipe_dump(_pipe_ablations(frame, runs, choice, market, cfg, rm, v4), "ablations.json", cfg)

    # step 11: leakage tests incl. shuffled-label run
    shuf, _, shuf_infos = run_schedule(frame, full, cfg, shuffle=True)
    leak = _pipe_leakage(frame, filings, full, event_cols, shuf, choice, market, cfg, rm, infos, shuf_infos, v4)
    _pipe_dump(leak, "leakage_tests.json", cfg)
    assert leak["filings"]["flagged_without_filing"] == 0 and leak["filings"]["filing_after_eom"] == 0,         f"leakage: filing_date after eom / flagged without filing: {leak['filings']}"
    assert leak["window_violations"] == 0, "leakage: train < val < test window ordering violated"
    assert not leak["train_target_month_violations"], f"leakage: training target months reach test year: {leak['train_target_month_violations']}"
    assert not leak["target_like_features"], f"leakage: target-identical features: {leak['target_like_features']}"
    assert leak["duplicate_permno_eom"] == 0, "leakage: duplicate (permno, eom) keys"
    _pipe_log("pipeline complete")
    if cfg.get("agent_enabled"):
        try:
            run_agent(cfg)
        except Exception as e:
            print(f"[agent] warning: explanation agent failed: {e}")


if __name__ == "__main__":
    main(CONFIG)
